"""iContext v6 CLI. Semantic changes are completed by the current host agent."""
from __future__ import annotations

import argparse
import contextlib
import io
import json
import os
import sys
from pathlib import Path

from context_runtime import (VERSION, atomic_write, bounded, contracts_index, digest, input_hash,
                             inventory, publish_layer, read_json, repository_lock,
                             validate_readmes, validate_seed, write_json, query_orientation, _context_budget)

PROJECTS = ("iDirectory", "ThinkingSeed", "MetricsThinking", "iReadme")


def ecosystem_root(value=None):
    if value:
        return Path(value).resolve()
    here = Path(__file__).resolve()
    for parent in here.parents:
        if (parent / "iDirectory").is_dir():
            return parent
    registered = read_json(Path.home() / ".icontext/registry.json").get("ecosystem_root")
    if registered:
        return Path(registered)
    return Path.cwd().resolve().parent


def outputs(root, layer):
    if layer == "seed":
        return sorted((root / "01_seed").glob("seed-*-master.md")) if (root / "01_seed").is_dir() else []
    if layer == "hybrid":
        return sorted(p for p in (root / "01_seed").glob("seed-*.md") if not p.name.endswith("-master.md")) if (root / "01_seed").is_dir() else []
    if layer == "readme":
        return [root / "README.md", root / "README_ES.md"]
    return [root / "artifacts/plans/metricsthinking" / name for name in
            ("MetricsThinking.json", "MetricsThinking.md", "INFERRED_ROADMAP.md", "CONTEXT_PRUNING_PLAN.json")]


def output_hash(root, layer):
    return digest({p.relative_to(root).as_posix(): digest(p.read_bytes()) if p.is_file() else None
                   for p in outputs(root, layer)})


def layer_hash(inv, layer, root):
    base = input_hash(inv, "seed" if layer == "hybrid" else layer)
    if layer == "metrics":
        # A consumer's evidence may be unchanged after its audit runtime upgrades.
        directory = Path(__file__).resolve().parent
        release = read_json(directory / "release_manifest.json")
        rules = {k: v for k, v in release.get("files", {}).items() if k.startswith("metricsthinking/")}
        if not rules:  # Installed wheels contain package resources, not the outer manifest.
            package = directory / "metricsthinking"
            rules = {p.relative_to(package).as_posix(): digest(p.read_bytes())
                     for p in package.rglob("*") if p.is_file() and p.suffix in {".py", ".yaml"}}
        return digest([base, VERSION, rules])
    if layer == "readme":
        return digest([base, output_hash(root, "metrics"), read_json(root / ".context/benchmark_v6.json")])
    return base


def plan(root, full=False):
    inv, delta = inventory(root, full=full)
    state = read_json(root / ".context/sync_state.json")
    layers = {}
    for layer in ("seed", "metrics", "readme"):
        previous = state.get(layer, {})
        fingerprint = layer_hash(inv, layer, root)
        exists = bool(outputs(root, layer)) and all(p.is_file() for p in outputs(root, layer))
        current = (previous.get("input_hash") == fingerprint and exists
                   and previous.get("output_hash") == output_hash(root, layer))
        layers[layer] = {"state": "current" if current else "pending", "input_hash": fingerprint}
    return {"version": VERSION, "project": root.name, "delta": delta, "layers": layers}, inv


def status(root):
    """Recorded status; never scan, mutate, or pretend to verify live freshness."""
    return {"version": VERSION, "project": root.name, "freshness": "recorded; use audit to verify",
            "layers": read_json(root / ".context/icontext_bus.json").get("layers", {}),
            "pending": read_json(root / ".context/update_request.json").get("requests", []),
            "toolchain": read_json(root / ".context/toolchain.json")}


def audit(root, full=False):
    result, inv = plan(root, full)
    errors = [f"{path}: {record['parse_error']}" for path, record in inv["files"].items() if record.get("parse_error")]
    for seed in outputs(root, "seed"):
        errors.extend(validate_seed(seed))
    if not outputs(root, "seed"):
        errors.append("SeedMaster missing")
    errors.extend(validate_readmes(root))
    bus = read_json(root / ".context/icontext_bus.json")
    if bus.get("protocol_version") != VERSION:
        errors.append("Missing or unsupported v6 federation bus")
    for short, name in (("l0", "l0_idirectory"), ("l1", "l1_thinkingseed"),
                        ("l2", "l2_metricsthinking"), ("l3", "l3_ireadme")):
        record = read_json(root / ".context/layers" / (name + ".json"))
        if not record or record != bus.get("layers", {}).get(name):
            errors.append(name + ": missing producer state or aggregate mismatch")
        elif record.get("state") not in {"recorded", "validated"}:
            errors.append(name + ": state is not verified evidence")
        if short == "l0" and record.get("inputs_hash") != inv["inputs_hash"]:
            errors.append("L0 inventory is stale")
    if any(v["state"] != "current" for v in result["layers"].values()):
        errors.append("Layers are pending or stale; run sync")
    result["errors"] = errors
    result["state"] = "invalid" if errors else "valid"
    return result


def request(root, layer, inv, fingerprint, delta):
    changed = sorted(set(delta["added"] + delta["modified"] + delta["removed"]))
    # Include contract differences since the last accepted semantic update.
    prior = read_json(root / ".context/sync_state.json").get(layer, {}).get("files", {})
    changed = sorted(set(changed) | {k for k, v in inv["files"].items() if prior.get(k) != v["sha256"]}
                     | (set(prior) - set(inv["files"])))
    return {"layer": layer, "input_hash": fingerprint,
            "changed_files": changed, "sections": ["2", "3", "4", "7", "9"] if layer in {"seed", "hybrid"} else ["2", "4", "5", "6"],
            "contract_files": [k for k in changed if k in inv["files"] and "contracts" in inv["files"][k]],
            "instruction": "Current agent: inspect changed evidence, update affected sections only, preserve other content, then run complete with this input hash."}


def complete(root, layer, expected):
    inv, _ = inventory(root)
    actual = layer_hash(inv, layer, root)
    if expected != actual:
        raise ValueError("Inputs changed during redaction; run sync again before completing")
    errors = []
    if layer in {"seed", "hybrid"}:
        seeds = outputs(root, layer)
        if not seeds:
            errors.append("Requested architectural vector missing")
        for seed in seeds:
            index = {"modules": {k: v["contracts"] for k, v in inv["files"].items() if "contracts" in v}}
            errors.extend(validate_seed(seed, index if layer == "seed" else None))
    else:
        errors.extend(validate_readmes(root))
    if errors:
        raise ValueError("; ".join(errors))
    with repository_lock(root, "sync"):
        state = read_json(root / ".context/sync_state.json")
        state[layer] = {"input_hash": actual, "output_hash": output_hash(root, layer),
                        "files": {k: v["sha256"] for k, v in inv["files"].items()}}
        write_json(root / ".context/sync_state.json", state)
        publish_layer(root, "l1" if layer in {"seed", "hybrid"} else "l3",
                      {"present": True, "state": "validated", "inputs_hash": actual,
                       "artifact_kind": "hybrid" if layer == "hybrid" else ("master" if layer == "seed" else "readme"),
                       "output_hash": state[layer]["output_hash"]})
        pending = read_json(root / ".context/update_request.json")
        if pending:
            pending["requests"] = [r for r in pending.get("requests", []) if r["layer"] != layer]
            write_json(root / ".context/update_request.json", pending)
    return {"layer": layer, "state": "validated", "input_hash": actual}


def metrics(root, eco, full=False, profile="default"):
    candidate = eco / "MetricsThinking" / "src"
    if not candidate.is_dir():
        candidate = eco / "packages/metricsthinking/src"
    if not candidate.is_dir():
        candidate = Path(root) / "packages/metricsthinking/src"
    if candidate.is_dir():
        sys.path.insert(0, str(candidate))
    from metricsthinking.engine import run_audit
    with contextlib.redirect_stdout(io.StringIO()):
        run_audit(str(root), quiet=True, reconcile_plans=False, full=full, profile_name=profile)
    report = read_json(root / "artifacts/plans/metricsthinking/MetricsThinking.json")
    if not report:
        raise RuntimeError("Metrics produced no valid report")
    fpai = report.get("fpai") or {}
    security = report.get("security") or {}
    publish_layer(root, "l2", {"present": True, "state": "validated",
                              "inputs_hash": read_json(root / ".context/inventory.json").get("inputs_hash"),
                              "evaluation_hash": read_json(root / ".context/cache/audit_v6.json").get("key"),
                              "consolidated_score": report.get("consolidated_score"),
                              "fpai_pf_spectral": fpai.get("power_factor_spectral"),
                              "fpai_s_spectral": fpai.get("s_spectral"),
                              "security_gate": (1.0 if security["pii_matches_count"] == 0 else 0.0) if "pii_matches_count" in security else None,
                              "security_gate_basis": "pii_scan_only",
                              "report_path": "artifacts/plans/metricsthinking/MetricsThinking.json",
                              "output_hash": output_hash(root, "metrics")})
    return {"profile": report.get("profile_used"), "consolidated_score": report.get("consolidated_score"),
            "artifacts": [p.relative_to(root).as_posix() for p in outputs(root, "metrics")]}


def sync(root, eco, dry_run=False, full=False):
    if dry_run:
        result, _ = plan(root, full)
        result["dry_run"] = True
        return result, 0
    with repository_lock(root, "sync"):
        result, inv = plan(root, full)
        parse_errors = {path: record["parse_error"] for path, record in inv["files"].items() if record.get("parse_error")}
        if parse_errors:
            result.update(state="failed", errors=parse_errors)
            for value in result["layers"].values():
                value["state"] = "blocked_by_evidence"
            publish_layer(root, "l0", {"present": True, "state": "invalid", "errors": parse_errors})
            return result, 1
        # Persist once, then reuse the same records for contracts.
        write_json(root / ".context/inventory.json", inv)
        index, _ = contracts_index(root, persist=True)
        import fwengine
        fwengine._compile_context_packs(root, inv)
        publish_layer(root, "l0", {"present": True, "state": "recorded", "inputs_hash": inv["inputs_hash"],
                                  "contracts_ast_hash": index["contracts_ast_hash"]})
        state = read_json(root / ".context/sync_state.json")
        requests = []
        if result["layers"]["seed"]["state"] != "current":
            requests.append(request(root, "seed", inv, layer_hash(inv, "seed", root), result["delta"]))
            result["layers"]["metrics"]["state"] = "blocked_by_seed"
            result["layers"]["readme"]["state"] = "blocked_by_seed"
        else:
            if result["layers"]["metrics"]["state"] != "current":
                try:
                    metrics(root, eco, full=full)
                except Exception as exc:
                    result["layers"]["metrics"].update(state="failed", error=str(exc))
                    result["layers"]["readme"]["state"] = "blocked_by_metrics"
                    return result, 1
                state["metrics"] = {"input_hash": layer_hash(inv, "metrics", root), "output_hash": output_hash(root, "metrics")}
                write_json(root / ".context/sync_state.json", state)
                result["layers"]["metrics"]["state"] = "updated"
            readme_fp = layer_hash(inv, "readme", root)
            result["layers"]["readme"]["input_hash"] = readme_fp
            previous = state.get("readme", {})
            if previous.get("input_hash") != readme_fp or previous.get("output_hash") != output_hash(root, "readme"):
                requests.append(request(root, "readme", inv, readme_fp, result["delta"]))
                result["layers"]["readme"]["state"] = "pending"
        write_json(root / ".context/update_request.json", {"version": VERSION, "requests": requests})
        result["requests"] = requests
        result["state"] = "pending_agent" if requests else "current"
        return result, 3 if requests else 0


def pack(root, path=".", tier="1a", expand=False, task=""):
    if tier == "2":
        import fwengine
        return fwengine.build_ecosystem_pack(root, expand=expand)
    # Bound after adding task information so the complete payload fits.
    payload = query_orientation(root, path, tier=tier, expand=True)
    if payload is None:
        import fwengine
        payload = fwengine.build_context_pack(root, path, tier=tier, expand=True)
    if task:
        payload["objective"] = task[:160]
    if expand:
        payload["contracts_ast"] = [s for k, m in read_json(root / ".context/contracts_ast.json").get("modules", {}).items()
                                    if path == "." or k.startswith(path.rstrip("/") + "/") for s in m.get("signatures", [])]
        return payload
    return bounded(payload, _context_budget(root, tier))


def main(argv=None):
    for stream in (sys.stdout, sys.stderr):
        if hasattr(stream, "reconfigure"):
            stream.reconfigure(encoding="utf-8", errors="replace")
    parser = argparse.ArgumentParser(prog="icontext", description="iContext v6 incremental context engineering")
    sub = parser.add_subparsers(dest="command")
    for name, aliases in (("status", []), ("pack", ["capsule"]), ("sync", ["reconcile", "update"]),
                          ("audit", []), ("doctor", ["fix"]), ("complete", []), ("prepare", []),
                          ("metrics", []), ("index", []), ("checkpoint", []), ("init", []), ("install", []), ("benchmark", [])):
        child = sub.add_parser(name, aliases=aliases)
        child.add_argument("--target", default=None)
        child.add_argument("--root", default=None)
        child.add_argument("--all", action="store_true")
        child.add_argument("--json", action="store_true")
        child.add_argument("--verbose", "-v", action="store_true")
        if name in {"sync", "install"}:
            child.add_argument("--dry-run", action="store_true")
        if name in {"sync", "audit", "metrics", "index"}:
            child.add_argument("--full", action="store_true")
        if name == "metrics":
            child.add_argument("--profile", default="default")
        if name == "pack":
            child.add_argument("path", nargs="?", default=".")
            child.add_argument("--tier", choices=["1a", "1b", "2"], default="1a")
            child.add_argument("--task", default="")
            child.add_argument("--expand", action="store_true")
        if name == "init":
            child.add_argument("path", nargs="?", default=".")
        if name == "doctor":
            child.add_argument("--fix", action="store_true")
        if name == "complete":
            child.add_argument("layer", choices=["seed", "hybrid", "readme"])
            child.add_argument("--input-hash", required=True)
        if name == "prepare":
            child.add_argument("layer", choices=["seed", "hybrid", "readme"])
        if name == "checkpoint":
            child.add_argument("--expand", action="store_true")
            child.add_argument("--session-id")
            child.add_argument("--objective")
            child.add_argument("--constraint", action="append", dest="constraints")
            child.add_argument("--decision", action="append", dest="decisions")
            child.add_argument("--next", dest="next_action")
            child.add_argument("--set", action="store_true")
            child.add_argument("--show", action="store_true")
            child.add_argument("--evidence-hash")
        if name == "install":
            child.add_argument("--agents", default="antigravity,codex")
            child.add_argument("--home", default=None)
            child.add_argument("--local", action="store_true")
    # Legacy global flags before subcommand are normalized to subcommand options.
    argv = list(sys.argv[1:] if argv is None else argv)
    commands = set(sub.choices)
    command_index = next((i for i, arg in enumerate(argv) if arg in commands), None)
    if command_index:
        argv = argv[command_index:] + argv[:command_index]
    args = parser.parse_args(argv)
    if not args.command:
        parser.print_help()
        return 0
    eco = ecosystem_root(args.root)
    target = Path(args.target or Path.cwd()).resolve()
    if args.command in {"pack", "capsule"}:
        target_path = ((Path(args.target) / args.path) if args.target else Path(args.path)).resolve()
        root = target_path
        while root != root.parent and not ((root / ".context").is_dir() or (root / ".git").exists()
                or (root / "pyproject.toml").is_file()
                or ((root / "FWengine.py").is_file() and (root / "tools/icontext_runtime/release_manifest.json").is_file())):
            root = root.parent
        if root == root.parent:
            root = target_path
        relative = target_path.relative_to(root).as_posix()
        if target_path.is_file():
            relative = target_path.parent.relative_to(root).as_posix()
        try:
            if args.command == "capsule":
                import fwengine
                payload = fwengine.build_context_capsule(root, relative, args.task)
            else:
                payload = pack(root, relative, args.tier, args.expand, args.task)
            print(json.dumps(payload, ensure_ascii=False, separators=(",", ":")))
            return 0
        except (OSError, ValueError) as exc:
            print(json.dumps({"error": str(exc)}))
            return 1
    if args.all:
        roots = []
        for p in PROJECTS:
            pkg = eco / "packages" / p.lower()
            if not pkg.is_dir() and (Path.cwd() / "packages" / p.lower()).is_dir():
                pkg = Path.cwd() / "packages" / p.lower()
            roots.append(pkg if pkg.is_dir() else eco / p)
    else:
        roots = [target]
    results, code = [], 0
    for root in roots:
        if not root.is_dir():
            results.append({"project": root.name, "state": "failed", "error": "Target directory missing"})
            code = 1
            continue
        try:
            if args.command == "status":
                result = status(root)
            elif args.command == "init":
                import fwengine
                with contextlib.redirect_stdout(io.StringIO()):
                    fwengine.init_project(str(Path(args.target or args.path).resolve()))
                result = {"project": root.name, "state": "initialized"}
            elif args.command in {"sync", "reconcile", "update"}:
                result, rc = sync(root, eco, args.dry_run, args.full)
                code = 1 if code == 1 or rc == 1 else max(code, rc)
            elif args.command == "complete":
                result = complete(root, args.layer, args.input_hash)
            elif args.command == "prepare":
                inv, delta = inventory(root)
                result = request(root, args.layer, inv, layer_hash(inv, args.layer, root), delta)
            elif args.command == "metrics":
                summary = metrics(root, eco, full=args.full, profile=args.profile)
                result = {"project": root.name, "state": "updated", **summary}
            elif args.command == "checkpoint":
                import fwengine
                result = fwengine.manage_checkpoint(root, action="set" if args.set else "show",
                         session_id=args.session_id, objective=args.objective, constraints=args.constraints,
                         decisions=args.decisions, next_action=args.next_action, evidence_hash=args.evidence_hash)
                if not args.expand:
                    result = fwengine._checkpoint_display(result)
            elif args.command == "index":
                idx, delta = contracts_index(root, persist=True, full=args.full)
                import fwengine
                fwengine._compile_context_packs(root, read_json(root / ".context/inventory.json"))
                publish_layer(root, "l0", {"present": True, "state": "recorded", "inputs_hash": idx["inputs_hash"],
                                          "contracts_ast_hash": idx["contracts_ast_hash"]})
                result = {"project": root.name, "state": "indexed", "delta": delta}
            elif args.command == "install":
                from skill_installer import install
                result = install(eco, args.agents.split(","), Path(args.home).resolve() if args.home else Path.home(),
                                 local=root if args.local else None, dry_run=args.dry_run)
            elif args.command == "benchmark":
                from benchmark import benchmark
                result = benchmark(root)
            elif args.command in {"doctor", "fix"}:
                from skill_installer import inspect_installation
                result = inspect_installation(eco, Path.home())
                if args.command == "fix" or args.fix:
                    from skill_installer import install
                    result = install(eco, ["antigravity", "codex"], Path.home())
                    import fwengine
                    with contextlib.redirect_stdout(io.StringIO()):
                        repaired = fwengine.reconcile_repository(root)
                    result["topology_repaired"] = repaired
                    if not repaired:
                        result["state"] = "failed"
                        code = 1
                elif result.get("errors"):
                    code = 1
                if not (args.command == "fix" or args.fix):
                    result["repository"] = audit(root)
                    if result["repository"]["errors"]:
                        result["state"] = "invalid"
                        code = 1
            else:
                result = audit(root, args.full)
                if result["errors"]:
                    code = 1
        except Exception as exc:
            result = {"project": root.name, "state": "failed", "error": str(exc)}
            code = 1
        results.append(result)
    if args.command == "checkpoint" and not args.expand:
        print(json.dumps(results[0], ensure_ascii=False, separators=(",", ":")))
    elif args.json:
        print(json.dumps(results if args.all else results[0], ensure_ascii=False, indent=2))
    else:
        for result in results:
            print(f"{result.get('project', target.name)}: {result.get('state', 'recorded')}")
            if "consolidated_score" in result:
                print(f"  profile: {result.get('profile')}; score: {result['consolidated_score']}")
            for layer, value in result.get("layers", {}).items():
                print(f"  {layer}: {value.get('state', 'recorded')}")
            for entry in result.get("requests", []):
                print(f"  Agent redaction pending: {entry['layer']} ({len(entry['changed_files'])} changed files); use --json")
            if result.get("error"):
                print(result["error"], file=sys.stderr)
            if args.verbose:
                print(json.dumps(result, ensure_ascii=False, indent=2))
    return code


if __name__ == "__main__":
    raise SystemExit(main())

"""iContext v6 portable runtime. Standard library only; queries never persist state.

Canonical source: iDirectory/src/core/context_runtime.py. Other copies are generated.
"""
from __future__ import annotations

import fnmatch
import hashlib
import json
import os
import re
import time
from contextlib import contextmanager
from datetime import datetime, timezone
from pathlib import Path

VERSION = "6.0.0"
ANALYZER_VERSION = "6.0.0:3"
EXCLUDED = {".git", ".context", ".venv", "venv", "env", "__pycache__", "node_modules",
            ".pytest_cache", ".mypy_cache", ".ruff_cache", "target", "dist", "build"}
PRUNED = {"data/raw", "data/processed", "data/sandbox", "logs", "artifacts/plans/archive",
          "artifacts/plans/backlog", "artifacts/plans/metricsthinking", "tools/icontext_runtime"}
LAYER_NAMES = {"l0": "l0_idirectory", "l1": "l1_thinkingseed", "l2": "l2_metricsthinking", "l3": "l3_ireadme"}


def read_json(path, default=None):
    try:
        return json.loads(Path(path).read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return {} if default is None else default


def digest(value):
    data = value if isinstance(value, bytes) else json.dumps(value, sort_keys=True, ensure_ascii=False).encode("utf-8")
    return hashlib.sha256(data).hexdigest()


def atomic_write(path, content):
    """Replace only changed bytes. Return whether a file was written."""
    import uuid
    path = Path(path)
    data = content.encode("utf-8") if isinstance(content, str) else content
    try:
        if path.read_bytes() == data:
            return False
    except FileNotFoundError:
        pass
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(f".tmp_{os.getpid()}_{uuid.uuid4().hex}_{path.name}")
    try:
        tmp.write_bytes(data)
        for attempt in range(10):
            try:
                os.replace(tmp, path)
                break
            except PermissionError:
                if attempt == 9:
                    raise
                time.sleep(0.01 * (1.5 ** attempt))
    finally:
        tmp.unlink(missing_ok=True)
    return True


def write_json(path, value):
    return atomic_write(path, json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2) + "\n")


@contextmanager
def repository_lock(root, name="publish", timeout=10):
    """OS lock: automatically released on process death; no stale-lock stealing."""
    path = Path(root) / ".context" / f".{name}.lock"
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("a+b") as handle:
        if path.stat().st_size == 0:
            handle.write(b"0")
            handle.flush()
        deadline = time.monotonic() + timeout
        while True:
            try:
                handle.seek(0)
                if os.name == "nt":
                    import msvcrt
                    msvcrt.locking(handle.fileno(), msvcrt.LK_NBLCK, 1)
                else:
                    import fcntl
                    fcntl.flock(handle.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
                break
            except (OSError, BlockingIOError):
                if time.monotonic() >= deadline:
                    raise TimeoutError(f"Repository busy: {name}")
                time.sleep(0.02)
        try:
            yield
        finally:
            handle.seek(0)
            if os.name == "nt":
                import msvcrt
                msvcrt.locking(handle.fileno(), msvcrt.LK_UNLCK, 1)
            else:
                import fcntl
                fcntl.flock(handle.fileno(), fcntl.LOCK_UN)


def publish_layer(root, layer, payload):
    """Own one sidecar; aggregate all layers under a common process lock."""
    root = Path(root)
    name = LAYER_NAMES.get(layer, layer)
    with repository_lock(root):
        sidecar = root / ".context" / "layers" / f"{name}.json"
        previous = read_json(sidecar)
        value = {"version": VERSION, **payload}
        if {k: v for k, v in previous.items() if k != "published_at"} == value:
            value = previous
        else:
            value["published_at"] = datetime.now(timezone.utc).isoformat()
        write_json(sidecar, value)
        bus_path = root / ".context" / "icontext_bus.json"
        old_bus = read_json(bus_path)
        layers = dict(old_bus.get("layers", {}))
        for key in LAYER_NAMES.values():
            record = read_json(root / ".context" / "layers" / f"{key}.json")
            if record:
                layers[key] = record
            elif key not in layers:
                layers[key] = {"present": False, "state": "unknown"}
        for record in layers.values():
            record.setdefault("state", "legacy_unverified")
        bus = {"$schema": "../schemas/icontext_bus.schema.json", "protocol_version": VERSION, "project": root.name, "layers": layers}
        if {k: v for k, v in old_bus.items() if k != "updated_at"} == bus:
            return old_bus
        bus["updated_at"] = datetime.now(timezone.utc).isoformat()
        write_json(bus_path, bus)
        return bus


def ignore_patterns(root):
    patterns = []
    for name in (".gitignore", ".agentignore"):
        path = Path(root) / name
        if path.is_file():
            patterns.extend(line.strip() for line in path.read_text(encoding="utf-8").splitlines()
                            if line.strip() and not line.lstrip().startswith("#"))
    return patterns


def ignored(relative, patterns):
    result = False
    for pattern in patterns:
        negate = pattern.startswith("!")
        pattern = pattern.lstrip("!").strip("/")
        parts = relative.split("/")
        if (fnmatch.fnmatchcase(relative, pattern) or relative.startswith(pattern + "/")
                or ("/" not in pattern and any(fnmatch.fnmatchcase(p, pattern) for p in parts))):
            result = not negate
    return result


def crawl_allowed(directory):
    beacon = Path(directory) / ".context.yaml"
    if beacon.is_file():
        return not re.search(r"(?mi)^\s*crawl\s*:\s*false\s*(?:#.*)?$", beacon.read_text(encoding="utf-8"))
    return True


def iter_files(root, patterns=None):
    """Prune before descending, including inherited beacon restrictions."""
    root = Path(root).resolve()
    patterns = ignore_patterns(root) + (patterns or [])
    if not crawl_allowed(root):
        return
    for current, dirs, files in os.walk(root, followlinks=False):
        cur = Path(current)
        dirs[:] = sorted(d for d in dirs if d not in EXCLUDED
                         and not (cur / d).is_symlink()
                         and (cur / d).relative_to(root).as_posix() not in PRUNED
                         and not ignored((cur / d).relative_to(root).as_posix(), patterns)
                         and crawl_allowed(cur / d))
        for name in sorted(files):
            path = cur / name
            rel = path.relative_to(root).as_posix()
            if (path.is_symlink() or name.startswith(".tmp_") or name == ".DS_Store"
                    or name == "desktop.ini" or name.endswith((".pyc", ".coverage")) or ignored(rel, patterns)):
                continue
            if name.startswith(".") and name not in {".context.yaml", ".gitignore", ".agentignore", ".cursorrules"}:
                continue
            yield path


def python_contracts(source, relative):
    import ast
    tree = ast.parse(source)
    symbols, signatures, flags, imports = [], [], [], []
    for node in tree.body:
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and not node.name.startswith("_"):
            symbols.append(node.name)
            signatures.append(f"./{relative}::{node.name}({ast.unparse(node.args)}) -> {ast.unparse(node.returns) if node.returns else 'Any'}")
        elif isinstance(node, ast.ClassDef) and not node.name.startswith("_"):
            symbols.append(node.name)
            signatures.append(f"./{relative}::{node.name}(class)")
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            imports.extend(a.name for a in node.names)
        elif isinstance(node, ast.ImportFrom):
            imports.append(node.module or "")
        elif isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and node.func.attr == "add_argument":
            flags.extend(a.value for a in node.args if isinstance(a, ast.Constant) and isinstance(a.value, str) and a.value.startswith("-"))
    return {"symbols": symbols, "signatures": signatures, "cli_flags": sorted(set(flags)), "imports": sorted(set(imports))}


def inventory(root, persist=False, full=False):
    root = Path(root).resolve()
    path = root / ".context" / "inventory.json"
    previous = read_json(path)
    patterns = ignore_patterns(root)
    policy_hash = digest([patterns, ANALYZER_VERSION, read_json(root / "config/context_policy.json")])
    old = previous.get("files", {}) if previous.get("policy_hash") == policy_hash else {}
    records, reads, parses = {}, 0, 0
    for file in iter_files(root, patterns):
        rel = file.relative_to(root).as_posix()
        stat = file.stat()
        cached = old.get(rel, {})
        stamp = [stat.st_size, stat.st_mtime_ns]
        if not full and cached.get("stat") == stamp:
            records[rel] = cached
            continue
        raw = file.read_bytes()
        reads += 1
        record = {"stat": stamp, "sha256": digest(raw), "size": len(raw)}
        if rel in {"README.md", "README_ES.md"}:
            text = raw.decode("utf-8", errors="replace")
            text = re.sub(r"<!-- ICONTEXT-V6:TELEMETRY:START -->.*?<!-- ICONTEXT-V6:TELEMETRY:END -->", "", text, flags=re.S)
            text = re.sub(r"\n{3,}", "\n\n", text.strip())
            record["semantic_sha256"] = digest(text.encode("utf-8"))
        if file.suffix == ".py":
            if cached.get("sha256") == record["sha256"] and "contracts" in cached:
                record["contracts"] = cached["contracts"]
            else:
                parses += 1
                try:
                    record["contracts"] = python_contracts(raw.decode("utf-8-sig"), rel)
                except (SyntaxError, UnicodeError) as exc:
                    record["parse_error"] = str(exc)
        records[rel] = record
    before = previous.get("files", {})
    added = sorted(set(records) - set(before))
    removed = sorted(set(before) - set(records))
    modified = sorted(k for k in records.keys() & before.keys() if records[k]["sha256"] != before[k]["sha256"])
    renames = []
    for src in removed:
        for dest in added:
            if before[src]["sha256"] == records[dest]["sha256"]:
                renames.append({"from": src, "to": dest})
                break
    result = {"version": VERSION, "analyzer_version": ANALYZER_VERSION, "policy_hash": policy_hash,
              "files": records, "inputs_hash": digest({k: v.get("semantic_sha256", v["sha256"]) for k, v in records.items()})}
    if persist:
        write_json(path, result)
    return result, {"added": added, "modified": modified, "removed": removed, "renamed": renames,
                    "files_read": reads, "ast_parses": parses}


def contracts_index(root, persist=False, full=False):
    inv, stats = inventory(root, persist=persist, full=full)
    modules = {k: v["contracts"] for k, v in inv["files"].items() if "contracts" in v}
    result = {"version": "6.0", "analyzer_version": ANALYZER_VERSION, "project": Path(root).name,
              "$schema": "../schemas/contracts_ast.schema.json",
              "topology_hash": read_json(Path(root) / ".context/tree.json").get("topology_hash", ""),
              "inputs_hash": inv["inputs_hash"], "modules": modules,
              "public_symbols": sorted({s for m in modules.values() for s in m["symbols"]}),
              "cli_flags": sorted({s for m in modules.values() for s in m["cli_flags"]}),
              "signatures_1line": [s for m in modules.values() for s in m["signatures"]]}
    result["contracts_ast_hash"] = digest(modules)
    if persist:
        write_json(Path(root) / ".context/contracts_ast.json", result)
    return result, stats


def input_hash(inv, layer):
    files = inv["files"]
    if layer == "seed":
        files = {k: v for k, v in files.items() if not k.startswith("01_seed/") and k not in {"README.md", "README_ES.md"}}
    elif layer == "readme":
        files = {k: v for k, v in files.items() if k not in {"README.md", "README_ES.md"}}
    return digest({"analyzer": ANALYZER_VERSION, "policy": inv["policy_hash"], "files": {k: v.get("semantic_sha256", v["sha256"]) for k, v in files.items()}})


def estimated_tokens(value):
    text = value if isinstance(value, str) else json.dumps(value, ensure_ascii=False, separators=(",", ":"))
    return (len(text) + 2) // 3


def _context_budget(root, tier):
    path = Path(root) / "config/context_policy.json"
    policy = json.loads(path.read_text(encoding="utf-8")) if path.is_file() else {}
    if tier == "ecosystem":
        value = policy.get("budgets", {}).get("ecosystem_pack_max_tokens", 650)
    else:
        value = policy.get("profiles", {}).get("tier_" + tier, {}).get("target_token_budget", 220 if tier == "1a" else 800)
    if isinstance(value, bool) or not isinstance(value, int) or value <= 0:
        raise ValueError("Context token budget must be a positive integer")
    return value


def bounded(payload, limit, removable=("contracts_ast", "edges", "files", "active_topology", "layers")):
    result = json.loads(json.dumps(payload))
    omitted = 0
    for key in removable:
        while estimated_tokens(result) > limit and result.get(key):
            collection = result[key]
            if isinstance(collection, dict):
                collection.pop(next(reversed(collection)))
            elif isinstance(collection, list):
                collection.pop()
            else:
                result[key] = ""
            omitted += 1
            result["omitted"] = omitted
            result["expand"] = "--expand"
    if estimated_tokens(result) > limit:
        raise ValueError("Required context exceeds budget; use --expand")
    return result


def _orientation_stamp(root):
    result = []
    for name in (".agentignore", ".gitignore", "config/context_policy.json"):
        path = Path(root) / name
        if path.is_file():
            st = path.stat()
            result.append([name, st.st_size, st.st_mtime_ns])
    return result


def _orientation_beacons(root, target):
    parts = Path(target).parts
    if ".." in parts or Path(target).is_absolute():
        raise ValueError("Orientation target must remain relative to its project")
    directory = Path(root)
    content, blocked = [], False
    for component in (None, *parts):
        if component not in (None, "."):
            directory = directory / component
        path = directory / ".context.yaml"
        if path.is_file():
            raw = path.read_bytes()
            content.append(digest(raw))
            blocked = blocked or bool(re.search(r"(?mi)^\s*crawl\s*:\s*false\s*(?:#.*)?$", raw.decode("utf-8", errors="replace")))
    return digest(content), blocked


_ORIENTATION_READ_CACHE = {}


def query_orientation(root, target=".", tier="1a", expand=False):
    """Fast recorded view. Return None when a verified cache cannot be used."""
    root = Path(root)
    target = target.replace("\\", "/").removeprefix("./").rstrip("/") or "."
    (root / target).resolve().relative_to(root.resolve())
    cache_file = root / ".context/orientation_cache.json"
    if not cache_file.is_file():
        return None
    stamp = cache_file.stat().st_mtime_ns
    cached_stamp, table = _ORIENTATION_READ_CACHE.get(str(root), (None, {}))
    if cached_stamp != stamp:
        table = read_json(cache_file)
        _ORIENTATION_READ_CACHE[str(root)] = (stamp, table)
    entry = table.get("entries", {}).get(target)
    if not entry or table.get("policy_stamp") != _orientation_stamp(root):
        return None
    chain_hash, blocked = _orientation_beacons(root, target)
    if blocked:
        return {"idir_pack": "6.0", "focus": target, "crawl": False, "state": "pruned", "files": [], "edges": {}}
    if entry.get("beacon_chain_hash") != chain_hash:
        return None
    value = json.loads(json.dumps(entry["pack"]))
    value.update(tier=tier, state="recorded", generation=table.get("generation"))
    from stat import S_ISREG
    verified = []
    for item in value.get("files", []):
        name = item.rsplit("(~", 1)[0]
        path = root / target / name
        try:
            st = path.stat()
            if S_ISREG(st.st_mode):
                ratio = 3.6 if path.suffix.lower() in {".py", ".sql", ".json", ".yaml", ".yml", ".avsc", ".tf", ".sh", ".ps1", ".toml"} else 4
                binary = path.suffix.lower() in {".png", ".jpg", ".jpeg", ".gif", ".ico", ".webp", ".bmp", ".pbix", ".parquet", ".delta", ".avro", ".orc", ".feather", ".pdf", ".zip", ".tar", ".gz", ".7z", ".whl", ".pyc", ".pyd", ".so", ".dll", ".exe"}
                verified.append(f"{name}(~{0 if binary else max(1, int(st.st_size / ratio))}t)")
        except OSError:
            pass
    value["files"] = verified
    checkpoint = read_json(root / ".context/checkpoint.json")
    if (checkpoint.get("status") in {"executing", "approved", "paused"}
            and (not checkpoint.get("expires_at") or checkpoint["expires_at"] > datetime.now(timezone.utc).isoformat())):
        value["checkpoint"] = {"plan_id": checkpoint.get("plan_id"), "session_id": checkpoint.get("session_id"),
            "objective": checkpoint.get("objective", "")[:80], "constraints": [str(v)[:80] for v in checkpoint.get("constraints", [])[:2]],
            "phase": checkpoint.get("current_phase"), "next": checkpoint.get("next_action", "")[:80]}
    return value if expand else bounded(value, _context_budget(root, tier))


def validate_seed(path, index=None):
    text = Path(path).read_text(encoding="utf-8")
    errors = []
    if not re.search(r'<SEED_ARCHITECTURAL_VECTOR\b[^>]*contains_source_code="false"', text) or "</SEED_ARCHITECTURAL_VECTOR>" not in text:
        errors.append("Missing architectural vector container")
    if "CONTEXT HANDOFF" not in text or "0.1" not in text:
        errors.append("Missing receiver instructions or handoff")
    if not {str(n) for n in range(11)}.issubset(set(re.findall(r"(?m)^##\s+(\d+)\.", text))):
        errors.append("Missing numbered architectural sections 0 through 10")
    if index is not None:
        expected = {symbol for name, module in index.get("modules", {}).items()
                    if not (name.startswith("tests/") or "/tests/" in name) for symbol in module.get("symbols", [])}
        missing = sorted(symbol for symbol in expected if symbol not in text)
        if missing:
            errors.append("Missing public contracts: " + ", ".join(missing[:20]))
    if re.search(r"(?<![A-Za-z0-9_])[A-Za-z]:[/\\]|file:///|(?<![:/A-Za-z0-9])/(?:home|Users)/", text):
        errors.append("Local absolute path")
    for language, body in re.findall(r"```([^\n]*)\n(.*?)```", text, re.S):
        if language.strip() in {"yaml", "yml"} and body.lstrip().startswith("seed_schema_version:"):
            # Seed identity metadata is a contract, not implementation source.
            continue
        if language.strip() in {"python", "py", "sh", "bash", "ps1", "sql", "json", "yaml", "rust", "go"} and len(body.strip().splitlines()) > 5:
            errors.append("Implementation block exceeds five lines")
    return errors


def validate_readmes(root):
    errors = []
    headings = []
    for name, other in (("README.md", "README_ES.md"), ("README_ES.md", "README.md")):
        path = Path(root) / name
        if not path.is_file():
            errors.append(f"Missing {name}")
            continue
        text = path.read_text(encoding="utf-8")
        sections = re.findall(r"(?m)^##\s+(\d+)\.", text)
        headings.append(sections)
        if sections != [str(i) for i in range(1, 9)]:
            errors.append(f"{name}: expected eight ordered sections")
        # Absolute paths are valid in fenced terminal examples when users request
        # copy-pasteable commands. Keep authored prose free of machine-local paths.
        prose = re.sub(r"```.*?```", "", text, flags=re.S)
        if other not in text or re.search(r"(?<![A-Za-z0-9_])[A-Za-z]:[/\\]|file:///|(?<![:/A-Za-z0-9])/(?:home|Users)/", prose):
            errors.append(f"{name}: invalid language links or local paths")
    if len(headings) == 2 and headings[0] != headings[1]:
        errors.append("Language section mismatch")
    return errors

"""iContext v6 CLI. Semantic changes are completed by the current host agent."""
from __future__ import annotations

import argparse
import contextlib
import io
import json
import os
import sys
from pathlib import Path

from context_runtime import (VERSION, atomic_write, bounded, contracts_index, digest, input_hash,
                             inventory, publish_layer, read_json, repository_lock,
                             validate_readmes, validate_seed, write_json, query_orientation, _context_budget)

PROJECTS = ("iDirectory", "ThinkingSeed", "MetricsThinking", "iReadme")


def ecosystem_root(value=None):
    if value:
        return Path(value).resolve()
    here = Path(__file__).resolve()
    for parent in here.parents:
        if (parent / "iDirectory").is_dir():
            return parent
    registered = read_json(Path.home() / ".icontext/registry.json").get("ecosystem_root")
    if registered:
        return Path(registered)
    return Path.cwd().resolve().parent


def outputs(root, layer):
    if layer == "seed":
        return sorted((root / "01_seed").glob("seed-*-master.md")) if (root / "01_seed").is_dir() else []
    if layer == "hybrid":
        return sorted(p for p in (root / "01_seed").glob("seed-*.md") if not p.name.endswith("-master.md")) if (root / "01_seed").is_dir() else []
    if layer == "readme":
        return [root / "README.md", root / "README_ES.md"]
    return [root / "artifacts/plans/metricsthinking" / name for name in
            ("MetricsThinking.json", "MetricsThinking.md", "INFERRED_ROADMAP.md", "CONTEXT_PRUNING_PLAN.json")]


def output_hash(root, layer):
    return digest({p.relative_to(root).as_posix(): digest(p.read_bytes()) if p.is_file() else None
                   for p in outputs(root, layer)})


def layer_hash(inv, layer, root):
    base = input_hash(inv, "seed" if layer == "hybrid" else layer)
    if layer == "metrics":
        # A consumer's evidence may be unchanged after its audit runtime upgrades.
        directory = Path(__file__).resolve().parent
        release = read_json(directory / "release_manifest.json")
        rules = {k: v for k, v in release.get("files", {}).items() if k.startswith("metricsthinking/")}
        if not rules:  # Installed wheels contain package resources, not the outer manifest.
            package = directory / "metricsthinking"
            rules = {p.relative_to(package).as_posix(): digest(p.read_bytes())
                     for p in package.rglob("*") if p.is_file() and p.suffix in {".py", ".yaml"}}
        return digest([base, VERSION, rules])
    if layer == "readme":
        return digest([base, output_hash(root, "metrics"), read_json(root / ".context/benchmark_v6.json")])
    return base


def plan(root, full=False):
    inv, delta = inventory(root, full=full)
    state = read_json(root / ".context/sync_state.json")
    layers = {}
    for layer in ("seed", "metrics", "readme"):
        previous = state.get(layer, {})
        fingerprint = layer_hash(inv, layer, root)
        exists = bool(outputs(root, layer)) and all(p.is_file() for p in outputs(root, layer))
        current = (previous.get("input_hash") == fingerprint and exists
                   and previous.get("output_hash") == output_hash(root, layer))
        layers[layer] = {"state": "current" if current else "pending", "input_hash": fingerprint}
    return {"version": VERSION, "project": root.name, "delta": delta, "layers": layers}, inv


def status(root):
    """Recorded status; never scan, mutate, or pretend to verify live freshness."""
    return {"version": VERSION, "project": root.name, "freshness": "recorded; use audit to verify",
            "layers": read_json(root / ".context/icontext_bus.json").get("layers", {}),
            "pending": read_json(root / ".context/update_request.json").get("requests", []),
            "toolchain": read_json(root / ".context/toolchain.json")}


def audit(root, full=False):
    result, inv = plan(root, full)
    errors = [f"{path}: {record['parse_error']}" for path, record in inv["files"].items() if record.get("parse_error")]
    for seed in outputs(root, "seed"):
        errors.extend(validate_seed(seed))
    if not outputs(root, "seed"):
        errors.append("SeedMaster missing")
    errors.extend(validate_readmes(root))
    bus = read_json(root / ".context/icontext_bus.json")
    if bus.get("protocol_version") != VERSION:
        errors.append("Missing or unsupported v6 federation bus")
    for short, name in (("l0", "l0_idirectory"), ("l1", "l1_thinkingseed"),
                        ("l2", "l2_metricsthinking"), ("l3", "l3_ireadme")):
        record = read_json(root / ".context/layers" / (name + ".json"))
        if not record or record != bus.get("layers", {}).get(name):
            errors.append(name + ": missing producer state or aggregate mismatch")
        elif record.get("state") not in {"recorded", "validated"}:
            errors.append(name + ": state is not verified evidence")
        if short == "l0" and record.get("inputs_hash") != inv["inputs_hash"]:
            errors.append("L0 inventory is stale")
    if any(v["state"] != "current" for v in result["layers"].values()):
        errors.append("Layers are pending or stale; run sync")
    result["errors"] = errors
    result["state"] = "invalid" if errors else "valid"
    return result


def request(root, layer, inv, fingerprint, delta):
    changed = sorted(set(delta["added"] + delta["modified"] + delta["removed"]))
    # Include contract differences since the last accepted semantic update.
    prior = read_json(root / ".context/sync_state.json").get(layer, {}).get("files", {})
    changed = sorted(set(changed) | {k for k, v in inv["files"].items() if prior.get(k) != v["sha256"]}
                     | (set(prior) - set(inv["files"])))
    return {"layer": layer, "input_hash": fingerprint,
            "changed_files": changed, "sections": ["2", "3", "4", "7", "9"] if layer in {"seed", "hybrid"} else ["2", "4", "5", "6"],
            "contract_files": [k for k in changed if k in inv["files"] and "contracts" in inv["files"][k]],
            "instruction": "Current agent: inspect changed evidence, update affected sections only, preserve other content, then run complete with this input hash."}


def complete(root, layer, expected):
    inv, _ = inventory(root)
    actual = layer_hash(inv, layer, root)
    if expected != actual:
        raise ValueError("Inputs changed during redaction; run sync again before completing")
    errors = []
    if layer in {"seed", "hybrid"}:
        seeds = outputs(root, layer)
        if not seeds:
            errors.append("Requested architectural vector missing")
        for seed in seeds:
            index = {"modules": {k: v["contracts"] for k, v in inv["files"].items() if "contracts" in v}}
            errors.extend(validate_seed(seed, index if layer == "seed" else None))
    else:
        errors.extend(validate_readmes(root))
    if errors:
        raise ValueError("; ".join(errors))
    with repository_lock(root, "sync"):
        state = read_json(root / ".context/sync_state.json")
        state[layer] = {"input_hash": actual, "output_hash": output_hash(root, layer),
                        "files": {k: v["sha256"] for k, v in inv["files"].items()}}
        write_json(root / ".context/sync_state.json", state)
        publish_layer(root, "l1" if layer in {"seed", "hybrid"} else "l3",
                      {"present": True, "state": "validated", "inputs_hash": actual,
                       "artifact_kind": "hybrid" if layer == "hybrid" else ("master" if layer == "seed" else "readme"),
                       "output_hash": state[layer]["output_hash"]})
        pending = read_json(root / ".context/update_request.json")
        if pending:
            pending["requests"] = [r for r in pending.get("requests", []) if r["layer"] != layer]
            write_json(root / ".context/update_request.json", pending)
    return {"layer": layer, "state": "validated", "input_hash": actual}


def metrics(root, eco, full=False, profile="default"):
    candidate = eco / "MetricsThinking" / "src"
    if not candidate.is_dir():
        candidate = eco / "packages/metricsthinking/src"
    if not candidate.is_dir():
        candidate = Path(root) / "packages/metricsthinking/src"
    if candidate.is_dir():
        sys.path.insert(0, str(candidate))
    from metricsthinking.engine import run_audit
    with contextlib.redirect_stdout(io.StringIO()):
        run_audit(str(root), quiet=True, reconcile_plans=False, full=full, profile_name=profile)
    report = read_json(root / "artifacts/plans/metricsthinking/MetricsThinking.json")
    if not report:
        raise RuntimeError("Metrics produced no valid report")
    fpai = report.get("fpai") or {}
    security = report.get("security") or {}
    publish_layer(root, "l2", {"present": True, "state": "validated",
                              "inputs_hash": read_json(root / ".context/inventory.json").get("inputs_hash"),
                              "evaluation_hash": read_json(root / ".context/cache/audit_v6.json").get("key"),
                              "consolidated_score": report.get("consolidated_score"),
                              "fpai_pf_spectral": fpai.get("power_factor_spectral"),
                              "fpai_s_spectral": fpai.get("s_spectral"),
                              "security_gate": (1.0 if security["pii_matches_count"] == 0 else 0.0) if "pii_matches_count" in security else None,
                              "security_gate_basis": "pii_scan_only",
                              "report_path": "artifacts/plans/metricsthinking/MetricsThinking.json",
                              "output_hash": output_hash(root, "metrics")})
    return {"profile": report.get("profile_used"), "consolidated_score": report.get("consolidated_score"),
            "artifacts": [p.relative_to(root).as_posix() for p in outputs(root, "metrics")]}


def sync(root, eco, dry_run=False, full=False):
    if dry_run:
        result, _ = plan(root, full)
        result["dry_run"] = True
        return result, 0
    with repository_lock(root, "sync"):
        result, inv = plan(root, full)
        parse_errors = {path: record["parse_error"] for path, record in inv["files"].items() if record.get("parse_error")}
        if parse_errors:
            result.update(state="failed", errors=parse_errors)
            for value in result["layers"].values():
                value["state"] = "blocked_by_evidence"
            publish_layer(root, "l0", {"present": True, "state": "invalid", "errors": parse_errors})
            return result, 1
        # Persist once, then reuse the same records for contracts.
        write_json(root / ".context/inventory.json", inv)
        index, _ = contracts_index(root, persist=True)
        import fwengine
        fwengine._compile_context_packs(root, inv)
        publish_layer(root, "l0", {"present": True, "state": "recorded", "inputs_hash": inv["inputs_hash"],
                                  "contracts_ast_hash": index["contracts_ast_hash"]})
        state = read_json(root / ".context/sync_state.json")
        requests = []
        if result["layers"]["seed"]["state"] != "current":
            requests.append(request(root, "seed", inv, layer_hash(inv, "seed", root), result["delta"]))
            result["layers"]["metrics"]["state"] = "blocked_by_seed"
            result["layers"]["readme"]["state"] = "blocked_by_seed"
        else:
            if result["layers"]["metrics"]["state"] != "current":
                try:
                    metrics(root, eco, full=full)
                except Exception as exc:
                    result["layers"]["metrics"].update(state="failed", error=str(exc))
                    result["layers"]["readme"]["state"] = "blocked_by_metrics"
                    return result, 1
                state["metrics"] = {"input_hash": layer_hash(inv, "metrics", root), "output_hash": output_hash(root, "metrics")}
                write_json(root / ".context/sync_state.json", state)
                result["layers"]["metrics"]["state"] = "updated"
            readme_fp = layer_hash(inv, "readme", root)
            result["layers"]["readme"]["input_hash"] = readme_fp
            previous = state.get("readme", {})
            if previous.get("input_hash") != readme_fp or previous.get("output_hash") != output_hash(root, "readme"):
                requests.append(request(root, "readme", inv, readme_fp, result["delta"]))
                result["layers"]["readme"]["state"] = "pending"
        write_json(root / ".context/update_request.json", {"version": VERSION, "requests": requests})
        result["requests"] = requests
        result["state"] = "pending_agent" if requests else "current"
        return result, 3 if requests else 0


def pack(root, path=".", tier="1a", expand=False, task=""):
    if tier == "2":
        import fwengine
        return fwengine.build_ecosystem_pack(root, expand=expand)
    # Bound after adding task information so the complete payload fits.
    payload = query_orientation(root, path, tier=tier, expand=True)
    if payload is None:
        import fwengine
        payload = fwengine.build_context_pack(root, path, tier=tier, expand=True)
    if task:
        payload["objective"] = task[:160]
    if expand:
        payload["contracts_ast"] = [s for k, m in read_json(root / ".context/contracts_ast.json").get("modules", {}).items()
                                    if path == "." or k.startswith(path.rstrip("/") + "/") for s in m.get("signatures", [])]
        return payload
    return bounded(payload, _context_budget(root, tier))


def main(argv=None):
    for stream in (sys.stdout, sys.stderr):
        if hasattr(stream, "reconfigure"):
            stream.reconfigure(encoding="utf-8", errors="replace")
    parser = argparse.ArgumentParser(prog="icontext", description="iContext v6 incremental context engineering")
    sub = parser.add_subparsers(dest="command")
    for name, aliases in (("status", []), ("pack", ["capsule"]), ("sync", ["reconcile", "update"]),
                          ("audit", []), ("doctor", ["fix"]), ("complete", []), ("prepare", []),
                          ("metrics", []), ("index", []), ("checkpoint", []), ("init", []), ("install", []), ("benchmark", [])):
        child = sub.add_parser(name, aliases=aliases)
        child.add_argument("--target", default=None)
        child.add_argument("--root", default=None)
        child.add_argument("--all", action="store_true")
        child.add_argument("--json", action="store_true")
        child.add_argument("--verbose", "-v", action="store_true")
        if name in {"sync", "install"}:
            child.add_argument("--dry-run", action="store_true")
        if name in {"sync", "audit", "metrics", "index"}:
            child.add_argument("--full", action="store_true")
        if name == "metrics":
            child.add_argument("--profile", default="default")
        if name == "pack":
            child.add_argument("path", nargs="?", default=".")
            child.add_argument("--tier", choices=["1a", "1b", "2"], default="1a")
            child.add_argument("--task", default="")
            child.add_argument("--expand", action="store_true")
        if name == "init":
            child.add_argument("path", nargs="?", default=".")
        if name == "doctor":
            child.add_argument("--fix", action="store_true")
        if name == "complete":
            child.add_argument("layer", choices=["seed", "hybrid", "readme"])
            child.add_argument("--input-hash", required=True)
        if name == "prepare":
            child.add_argument("layer", choices=["seed", "hybrid", "readme"])
        if name == "checkpoint":
            child.add_argument("--expand", action="store_true")
            child.add_argument("--session-id")
            child.add_argument("--objective")
            child.add_argument("--constraint", action="append", dest="constraints")
            child.add_argument("--decision", action="append", dest="decisions")
            child.add_argument("--next", dest="next_action")
            child.add_argument("--set", action="store_true")
            child.add_argument("--show", action="store_true")
            child.add_argument("--evidence-hash")
        if name == "install":
            child.add_argument("--agents", default="antigravity,codex")
            child.add_argument("--home", default=None)
            child.add_argument("--local", action="store_true")
    # Legacy global flags before subcommand are normalized to subcommand options.
    argv = list(sys.argv[1:] if argv is None else argv)
    commands = set(sub.choices)
    command_index = next((i for i, arg in enumerate(argv) if arg in commands), None)
    if command_index:
        argv = argv[command_index:] + argv[:command_index]
    args = parser.parse_args(argv)
    if not args.command:
        parser.print_help()
        return 0
    eco = ecosystem_root(args.root)
    target = Path(args.target or Path.cwd()).resolve()
    if args.command in {"pack", "capsule"}:
        target_path = ((Path(args.target) / args.path) if args.target else Path(args.path)).resolve()
        root = target_path
        while root != root.parent and not ((root / ".context").is_dir() or (root / ".git").exists()
                or (root / "pyproject.toml").is_file()
                or ((root / "FWengine.py").is_file() and (root / "tools/icontext_runtime/release_manifest.json").is_file())):
            root = root.parent
        if root == root.parent:
            root = target_path
        relative = target_path.relative_to(root).as_posix()
        if target_path.is_file():
            relative = target_path.parent.relative_to(root).as_posix()
        try:
            if args.command == "capsule":
                import fwengine
                payload = fwengine.build_context_capsule(root, relative, args.task)
            else:
                payload = pack(root, relative, args.tier, args.expand, args.task)
            print(json.dumps(payload, ensure_ascii=False, separators=(",", ":")))
            return 0
        except (OSError, ValueError) as exc:
            print(json.dumps({"error": str(exc)}))
            return 1
    if args.all:
        roots = []
        for p in PROJECTS:
            pkg = eco / "packages" / p.lower()
            if not pkg.is_dir() and (Path.cwd() / "packages" / p.lower()).is_dir():
                pkg = Path.cwd() / "packages" / p.lower()
            roots.append(pkg if pkg.is_dir() else eco / p)
    else:
        roots = [target]
    results, code = [], 0
    for root in roots:
        if not root.is_dir():
            results.append({"project": root.name, "state": "failed", "error": "Target directory missing"})
            code = 1
            continue
        try:
            if args.command == "status":
                result = status(root)
            elif args.command == "init":
                import fwengine
                with contextlib.redirect_stdout(io.StringIO()):
                    fwengine.init_project(str(Path(args.target or args.path).resolve()))
                result = {"project": root.name, "state": "initialized"}
            elif args.command in {"sync", "reconcile", "update"}:
                result, rc = sync(root, eco, args.dry_run, args.full)
                code = 1 if code == 1 or rc == 1 else max(code, rc)
            elif args.command == "complete":
                result = complete(root, args.layer, args.input_hash)
            elif args.command == "prepare":
                inv, delta = inventory(root)
                result = request(root, args.layer, inv, layer_hash(inv, args.layer, root), delta)
            elif args.command == "metrics":
                summary = metrics(root, eco, full=args.full, profile=args.profile)
                result = {"project": root.name, "state": "updated", **summary}
            elif args.command == "checkpoint":
                import fwengine
                result = fwengine.manage_checkpoint(root, action="set" if args.set else "show",
                         session_id=args.session_id, objective=args.objective, constraints=args.constraints,
                         decisions=args.decisions, next_action=args.next_action, evidence_hash=args.evidence_hash)
                if not args.expand:
                    result = fwengine._checkpoint_display(result)
            elif args.command == "index":
                idx, delta = contracts_index(root, persist=True, full=args.full)
                import fwengine
                fwengine._compile_context_packs(root, read_json(root / ".context/inventory.json"))
                publish_layer(root, "l0", {"present": True, "state": "recorded", "inputs_hash": idx["inputs_hash"],
                                          "contracts_ast_hash": idx["contracts_ast_hash"]})
                result = {"project": root.name, "state": "indexed", "delta": delta}
            elif args.command == "install":
                from skill_installer import install
                result = install(eco, args.agents.split(","), Path(args.home).resolve() if args.home else Path.home(),
                                 local=root if args.local else None, dry_run=args.dry_run)
            elif args.command == "benchmark":
                from benchmark import benchmark
                result = benchmark(root)
            elif args.command in {"doctor", "fix"}:
                from skill_installer import inspect_installation
                result = inspect_installation(eco, Path.home())
                if args.command == "fix" or args.fix:
                    from skill_installer import install
                    result = install(eco, ["antigravity", "codex"], Path.home())
                    import fwengine
                    with contextlib.redirect_stdout(io.StringIO()):
                        repaired = fwengine.reconcile_repository(root)
                    result["topology_repaired"] = repaired
                    if not repaired:
                        result["state"] = "failed"
                        code = 1
                elif result.get("errors"):
                    code = 1
                if not (args.command == "fix" or args.fix):
                    result["repository"] = audit(root)
                    if result["repository"]["errors"]:
                        result["state"] = "invalid"
                        code = 1
            else:
                result = audit(root, args.full)
                if result["errors"]:
                    code = 1
        except Exception as exc:
            result = {"project": root.name, "state": "failed", "error": str(exc)}
            code = 1
        results.append(result)
    if args.command == "checkpoint" and not args.expand:
        print(json.dumps(results[0], ensure_ascii=False, separators=(",", ":")))
    elif args.json:
        print(json.dumps(results if args.all else results[0], ensure_ascii=False, indent=2))
    else:
        for result in results:
            print(f"{result.get('project', target.name)}: {result.get('state', 'recorded')}")
            if "consolidated_score" in result:
                print(f"  profile: {result.get('profile')}; score: {result['consolidated_score']}")
            for layer, value in result.get("layers", {}).items():
                print(f"  {layer}: {value.get('state', 'recorded')}")
            for entry in result.get("requests", []):
                print(f"  Agent redaction pending: {entry['layer']} ({len(entry['changed_files'])} changed files); use --json")
            if result.get("error"):
                print(result["error"], file=sys.stderr)
            if args.verbose:
                print(json.dumps(result, ensure_ascii=False, indent=2))
    return code


if __name__ == "__main__":
    raise SystemExit(main())

"""Versioned iContext bundles for Antigravity and Codex. Never replace user rules."""
import json
import os
import shutil
import sys
import time
from pathlib import Path

from context_runtime import VERSION, atomic_write, digest, read_json, write_json

SKILLS = {"idir": ("iDirectory", "skills/v6/idir"),
          "seed": ("ThinkingSeed", "skills/v6/seed"),
          "seed-master": ("ThinkingSeed", "skills/v6/seed-master"),
          "metrics": ("MetricsThinking", "skills/v6/metrics"),
          "readme": ("iReadme", "skills/v6/readme"),
          "icontext": ("ContextControl", "skills/v6/icontext")}

BOOTSTRAP = '''#!/usr/bin/env python3
"""Run the installed runtime, respecting a project version pin."""
import json
import sys
from pathlib import Path
sys.dont_write_bytecode = True
here = Path(__file__).resolve()
version = "6.0.0"
for root in (Path.cwd(), *Path.cwd().parents):
    pin = root / ".context/toolchain.json"
    if pin.is_file():
        version = str(json.loads(pin.read_text(encoding="utf-8")).get("runtime_version", version))
        break
    if (root / ".git").exists():
        break
if not version or any(c not in "0123456789." for c in version):
    raise SystemExit("Invalid runtime version pin")
candidates = [Path.home() / ".icontext/versions" / version]
for parent in here.parents:
    candidates.extend([parent / "icontext" / version, parent / ".icontext/versions" / version, parent / "tools/icontext_runtime"])
def matches_version(path):
    try:
        return (path / "icontext_cli.py").is_file() and json.loads((path / "release_manifest.json").read_text(encoding="utf-8")).get("version") == version
    except (OSError, ValueError):
        return False
runtime = next((p for p in candidates if matches_version(p)), None)
if runtime is None:
    raise SystemExit("Requested iContext runtime is not installed; run the v6 installer")
sys.path.insert(0, str(runtime))
from icontext_cli import main
raise SystemExit(main())
'''


def source_bundles(eco):
    result = {}
    for name, (repo, relative) in SKILLS.items():
        candidates = [
            Path(eco) / repo / relative,
            Path(eco) / "skills/v6" / name,
            Path(eco) / "packages" / repo.lower() / relative,
            Path(__file__).resolve().parent / "skill_bundles" / name,
            Path(__file__).resolve().parents[1] / "skills/v6" / name,
            Path(__file__).resolve().parents[2] / "skills/v6" / name,
        ]
        found = next((p for p in candidates if (p / "bundle.json").is_file()), Path(__file__).resolve().parent / "skill_bundles" / name)
        result[name] = found
    return result


def inspect_installation(eco, home):
    errors, installed = [], {}
    for agent, dest in (("antigravity", home / ".gemini/config/skills"), ("codex", home / ".agents/skills")):
        installed[agent] = {}
        for name, src in source_bundles(eco).items():
            target = dest / name / "SKILL.md"
            actual = digest(target.read_bytes()) if target.is_file() else None
            expected = digest((src / "SKILL.md").read_bytes()) if (src / "SKILL.md").is_file() else None
            manifest = read_json(src / "bundle.json")
            matches = bool(manifest) and actual == expected and actual is not None
            for relative, fingerprint in manifest.get("files", {}).items():
                resource = dest / name / relative
                matches = matches and resource.is_file() and digest(resource.read_bytes()) == fingerprint
            matches = matches and read_json(dest / name / "bundle.json") == manifest
            installed[agent][name] = {"matches": matches, "hash": actual}
            if not matches:
                errors.append(f"{agent}:{name}: missing or differs from canonical source")
    release = read_json(Path(__file__).resolve().parent / "release_manifest.json")
    runtime = home / ".icontext/versions" / VERSION
    if release:
        for relative, fingerprint in release.get("files", {}).items():
            resource = runtime / relative
            if not resource.is_file() or digest(resource.read_bytes()) != fingerprint:
                errors.append("runtime: missing or differs: " + relative)
    return {"version": VERSION, "state": "invalid" if errors else "current", "installed": installed, "errors": errors}


def install(eco, agents, home, local=None, dry_run=False, only=None, source_runtime=None):
    eco, home = Path(eco), Path(home)
    if any(agent not in {"antigravity", "codex", "claude"} for agent in agents):
        raise ValueError("Supported agents: antigravity,codex,claude")
    runtime_source = Path(source_runtime) if source_runtime else eco / "ContextControl/tools/icontext_runtime"
    if not (runtime_source / "release_manifest.json").is_file():
        runtime_source = Path(__file__).resolve().parent
    if not (runtime_source / "release_manifest.json").is_file():
        import tempfile
        import zipfile
        import _icontext_assets
        payload = Path(_icontext_assets.__file__).parent / "runtime_payload.zip"
        with tempfile.TemporaryDirectory(prefix="icontext_install_") as temporary:
            with zipfile.ZipFile(payload) as archive:
                for member in archive.infolist():
                    relative = Path(member.filename)
                    if relative.is_absolute() or ".." in relative.parts:
                        raise ValueError("Invalid runtime payload path")
                    atomic_write(Path(temporary) / relative, archive.read(member))
            return install(eco, agents, home, local=local, dry_run=dry_run, only=only, source_runtime=temporary)
    runtime_dest = (Path(local) / ".agents/icontext" if local else home / ".icontext/versions") / VERSION
    locations = {"antigravity": ".gemini/config/skills", "codex": ".agents/skills", "claude": ".claude/skills"}
    destinations = [Path(local) / ".agents/skills"] if local else [home / locations[a] for a in agents]
    selected = {k: (v if (v / "bundle.json").is_file() else runtime_source / "skill_bundles" / k)
                for k, v in source_bundles(eco).items() if only is None or k in only}
    result = {"version": VERSION, "state": "planned" if dry_run else "installed", "skills": list(selected),
              "agents": agents, "writes": 0}
    if dry_run:
        return result
    release = read_json(runtime_source / "release_manifest.json")
    for name, source in selected.items():
        manifest = read_json(source / "bundle.json")
        if manifest.get("version") != VERSION or not manifest.get("files"):
            raise ValueError(f"Missing or unsupported bundle manifest: {name}")
        for relative, fingerprint in manifest["files"].items():
            if digest((source / relative).read_bytes()) != fingerprint:
                raise ValueError(f"Bundle integrity error: {name}/{relative}")
    # Each release is assembled from its manifest, never from an unfiltered scan.
    for relative, fingerprint in release["files"].items():
        source = runtime_source / relative
        if digest(source.read_bytes()) != fingerprint:
            raise ValueError(f"Distribution integrity error: {relative}")
        result["writes"] += atomic_write(runtime_dest / relative, source.read_bytes())
    result["writes"] += atomic_write(runtime_dest / "release_manifest.json", (runtime_source / "release_manifest.json").read_bytes())
    for dest in destinations:
        for name, source in selected.items():
            manifest = read_json(source / "bundle.json")
            if not manifest:
                raise ValueError(f"Missing bundle manifest: {name}")
            for relative in manifest["files"]:
                target = dest / name / relative
                raw = (source / relative).read_bytes()
                if target.is_file() and target.read_bytes() != raw:
                    # Preserve user edits before replacing managed files.
                    backup = home / ".icontext/backups" / digest(str(target))[:12] / digest(target.read_bytes()) / relative
                    atomic_write(backup, target.read_bytes())
                result["writes"] += atomic_write(target, raw)
            result["writes"] += atomic_write(dest / name / "bundle.json", (source / "bundle.json").read_bytes())
    if not local:
        # Quarantine old iContext copies; other personal skills stay untouched.
        for old_root in (home / ".codex/skills", home / ".gemini/config/skills"):
            names = ("dir", "idir", "seed", "seedMaster", "metrics", "readme", "icontext") if old_root.name == "skills" and ".codex" in old_root.parts else ("seedMaster",)
            for name in names:
                if name not in selected and not (name == "seedMaster" and "seed-master" in selected) and not (name == "dir" and "idir" in selected):
                    continue
                target = old_root / name
                skill = target / "SKILL.md"
                if not skill.is_file():
                    continue
                text = skill.read_text(encoding="utf-8")
                if not any(marker in text for marker in ("iDirectory", "ThinkingSeed", "MetricsThinking", "Enterprise Paper-Grade", "iContext")):
                    continue
                resolved = target.resolve()
                resolved.relative_to(old_root.resolve())
                backup = home / ".icontext/backups/legacy" / digest(str(resolved))[:12] / name
                if backup.exists():
                    backup = backup.with_name(name + "_" + str(time.time_ns()))
                backup.parent.mkdir(parents=True, exist_ok=True)
                os.rename(resolved, backup)
        launcher = home / ".local/bin/icontext.py"
        atomic_write(launcher, BOOTSTRAP)
        if os.name == "nt":
            atomic_write(launcher.with_suffix(".cmd"), f'@"{sys.executable}" -B "{launcher}" %*\n')
            if home.resolve() == Path.home().resolve():
                import winreg
                with winreg.CreateKey(winreg.HKEY_CURRENT_USER, "Environment") as key:
                    try:
                        user_path, kind = winreg.QueryValueEx(key, "Path")
                    except FileNotFoundError:
                        user_path, kind = "", winreg.REG_EXPAND_SZ
                    directory = str(launcher.parent)
                    if directory.casefold() not in {p.rstrip("\\").casefold() for p in user_path.split(";")}:
                        winreg.SetValueEx(key, "Path", 0, kind, user_path.rstrip(";") + ";" + directory)
                result["path_registered"] = True
                # Notify future Explorer-launched terminals of the user PATH.
                import ctypes
                notify = ctypes.windll.user32.SendMessageTimeoutW
                notify.argtypes = [ctypes.c_void_p, ctypes.c_uint, ctypes.c_size_t,
                                   ctypes.c_wchar_p, ctypes.c_uint, ctypes.c_uint,
                                   ctypes.POINTER(ctypes.c_size_t)]
                notified = ctypes.c_size_t()
                notify(0xFFFF, 0x001A, 0, "Environment", 2, 1000, ctypes.byref(notified))
        else:
            command = launcher.with_suffix("")
            atomic_write(command, f'#!/bin/sh\nexec "{sys.executable}" -B "{launcher}" "$@"\n')
            command.chmod(0o755)
        write_json(home / ".icontext/registry.json", {"ecosystem_root": str(eco.resolve()), "runtime_version": VERSION})
    result["command"] = "icontext" if not local else "python .agents/skills/icontext/scripts/run.py"
    if not local:
        result["command_path"] = str((home / ".local/bin/icontext.cmd") if os.name == "nt" else (home / ".local/bin/icontext"))
    return result

"""iContext v6 portable runtime. Standard library only; queries never persist state.

Canonical source: iDirectory/src/core/context_runtime.py. Other copies are generated.
"""
from __future__ import annotations

import fnmatch
import hashlib
import json
import os
import re
import time
from contextlib import contextmanager
from datetime import datetime, timezone
from pathlib import Path

VERSION = "6.0.0"
ANALYZER_VERSION = "6.0.0:3"
EXCLUDED = {".git", ".context", ".venv", "venv", "env", "__pycache__", "node_modules",
            ".pytest_cache", ".mypy_cache", ".ruff_cache", "target", "dist", "build"}
PRUNED = {"data/raw", "data/processed", "data/sandbox", "logs", "artifacts/plans/archive",
          "artifacts/plans/backlog", "artifacts/plans/metricsthinking", "tools/icontext_runtime"}
LAYER_NAMES = {"l0": "l0_idirectory", "l1": "l1_thinkingseed", "l2": "l2_metricsthinking", "l3": "l3_ireadme"}


def read_json(path, default=None):
    try:
        return json.loads(Path(path).read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return {} if default is None else default


def digest(value):
    data = value if isinstance(value, bytes) else json.dumps(value, sort_keys=True, ensure_ascii=False).encode("utf-8")
    return hashlib.sha256(data).hexdigest()


def atomic_write(path, content):
    """Replace only changed bytes. Return whether a file was written."""
    import uuid
    path = Path(path)
    data = content.encode("utf-8") if isinstance(content, str) else content
    try:
        if path.read_bytes() == data:
            return False
    except FileNotFoundError:
        pass
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(f".tmp_{os.getpid()}_{uuid.uuid4().hex}_{path.name}")
    try:
        tmp.write_bytes(data)
        for attempt in range(10):
            try:
                os.replace(tmp, path)
                break
            except PermissionError:
                if attempt == 9:
                    raise
                time.sleep(0.01 * (1.5 ** attempt))
    finally:
        tmp.unlink(missing_ok=True)
    return True


def write_json(path, value):
    return atomic_write(path, json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2) + "\n")


@contextmanager
def repository_lock(root, name="publish", timeout=10):
    """OS lock: automatically released on process death; no stale-lock stealing."""
    path = Path(root) / ".context" / f".{name}.lock"
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("a+b") as handle:
        if path.stat().st_size == 0:
            handle.write(b"0")
            handle.flush()
        deadline = time.monotonic() + timeout
        while True:
            try:
                handle.seek(0)
                if os.name == "nt":
                    import msvcrt
                    msvcrt.locking(handle.fileno(), msvcrt.LK_NBLCK, 1)
                else:
                    import fcntl
                    fcntl.flock(handle.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
                break
            except (OSError, BlockingIOError):
                if time.monotonic() >= deadline:
                    raise TimeoutError(f"Repository busy: {name}")
                time.sleep(0.02)
        try:
            yield
        finally:
            handle.seek(0)
            if os.name == "nt":
                import msvcrt
                msvcrt.locking(handle.fileno(), msvcrt.LK_UNLCK, 1)
            else:
                import fcntl
                fcntl.flock(handle.fileno(), fcntl.LOCK_UN)


def publish_layer(root, layer, payload):
    """Own one sidecar; aggregate all layers under a common process lock."""
    root = Path(root)
    name = LAYER_NAMES.get(layer, layer)
    with repository_lock(root):
        sidecar = root / ".context" / "layers" / f"{name}.json"
        previous = read_json(sidecar)
        value = {"version": VERSION, **payload}
        if {k: v for k, v in previous.items() if k != "published_at"} == value:
            value = previous
        else:
            value["published_at"] = datetime.now(timezone.utc).isoformat()
        write_json(sidecar, value)
        bus_path = root / ".context" / "icontext_bus.json"
        old_bus = read_json(bus_path)
        layers = dict(old_bus.get("layers", {}))
        for key in LAYER_NAMES.values():
            record = read_json(root / ".context" / "layers" / f"{key}.json")
            if record:
                layers[key] = record
            elif key not in layers:
                layers[key] = {"present": False, "state": "unknown"}
        for record in layers.values():
            record.setdefault("state", "legacy_unverified")
        bus = {"$schema": "../schemas/icontext_bus.schema.json", "protocol_version": VERSION, "project": root.name, "layers": layers}
        if {k: v for k, v in old_bus.items() if k != "updated_at"} == bus:
            return old_bus
        bus["updated_at"] = datetime.now(timezone.utc).isoformat()
        write_json(bus_path, bus)
        return bus


def ignore_patterns(root):
    patterns = []
    for name in (".gitignore", ".agentignore"):
        path = Path(root) / name
        if path.is_file():
            patterns.extend(line.strip() for line in path.read_text(encoding="utf-8").splitlines()
                            if line.strip() and not line.lstrip().startswith("#"))
    return patterns


def ignored(relative, patterns):
    result = False
    for pattern in patterns:
        negate = pattern.startswith("!")
        pattern = pattern.lstrip("!").strip("/")
        parts = relative.split("/")
        if (fnmatch.fnmatchcase(relative, pattern) or relative.startswith(pattern + "/")
                or ("/" not in pattern and any(fnmatch.fnmatchcase(p, pattern) for p in parts))):
            result = not negate
    return result


def crawl_allowed(directory):
    beacon = Path(directory) / ".context.yaml"
    if beacon.is_file():
        return not re.search(r"(?mi)^\s*crawl\s*:\s*false\s*(?:#.*)?$", beacon.read_text(encoding="utf-8"))
    return True


def iter_files(root, patterns=None):
    """Prune before descending, including inherited beacon restrictions."""
    root = Path(root).resolve()
    patterns = ignore_patterns(root) + (patterns or [])
    if not crawl_allowed(root):
        return
    for current, dirs, files in os.walk(root, followlinks=False):
        cur = Path(current)
        dirs[:] = sorted(d for d in dirs if d not in EXCLUDED
                         and not (cur / d).is_symlink()
                         and (cur / d).relative_to(root).as_posix() not in PRUNED
                         and not ignored((cur / d).relative_to(root).as_posix(), patterns)
                         and crawl_allowed(cur / d))
        for name in sorted(files):
            path = cur / name
            rel = path.relative_to(root).as_posix()
            if (path.is_symlink() or name.startswith(".tmp_") or name == ".DS_Store"
                    or name == "desktop.ini" or name.endswith((".pyc", ".coverage")) or ignored(rel, patterns)):
                continue
            if name.startswith(".") and name not in {".context.yaml", ".gitignore", ".agentignore", ".cursorrules"}:
                continue
            yield path


def python_contracts(source, relative):
    import ast
    tree = ast.parse(source)
    symbols, signatures, flags, imports = [], [], [], []
    for node in tree.body:
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and not node.name.startswith("_"):
            symbols.append(node.name)
            signatures.append(f"./{relative}::{node.name}({ast.unparse(node.args)}) -> {ast.unparse(node.returns) if node.returns else 'Any'}")
        elif isinstance(node, ast.ClassDef) and not node.name.startswith("_"):
            symbols.append(node.name)
            signatures.append(f"./{relative}::{node.name}(class)")
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            imports.extend(a.name for a in node.names)
        elif isinstance(node, ast.ImportFrom):
            imports.append(node.module or "")
        elif isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and node.func.attr == "add_argument":
            flags.extend(a.value for a in node.args if isinstance(a, ast.Constant) and isinstance(a.value, str) and a.value.startswith("-"))
    return {"symbols": symbols, "signatures": signatures, "cli_flags": sorted(set(flags)), "imports": sorted(set(imports))}


def inventory(root, persist=False, full=False):
    root = Path(root).resolve()
    path = root / ".context" / "inventory.json"
    previous = read_json(path)
    patterns = ignore_patterns(root)
    policy_hash = digest([patterns, ANALYZER_VERSION, read_json(root / "config/context_policy.json")])
    old = previous.get("files", {}) if previous.get("policy_hash") == policy_hash else {}
    records, reads, parses = {}, 0, 0
    for file in iter_files(root, patterns):
        rel = file.relative_to(root).as_posix()
        stat = file.stat()
        cached = old.get(rel, {})
        stamp = [stat.st_size, stat.st_mtime_ns]
        if not full and cached.get("stat") == stamp:
            records[rel] = cached
            continue
        raw = file.read_bytes()
        reads += 1
        record = {"stat": stamp, "sha256": digest(raw), "size": len(raw)}
        if rel in {"README.md", "README_ES.md"}:
            text = raw.decode("utf-8", errors="replace")
            text = re.sub(r"<!-- ICONTEXT-V6:TELEMETRY:START -->.*?<!-- ICONTEXT-V6:TELEMETRY:END -->", "", text, flags=re.S)
            text = re.sub(r"\n{3,}", "\n\n", text.strip())
            record["semantic_sha256"] = digest(text.encode("utf-8"))
        if file.suffix == ".py":
            if cached.get("sha256") == record["sha256"] and "contracts" in cached:
                record["contracts"] = cached["contracts"]
            else:
                parses += 1
                try:
                    record["contracts"] = python_contracts(raw.decode("utf-8-sig"), rel)
                except (SyntaxError, UnicodeError) as exc:
                    record["parse_error"] = str(exc)
        records[rel] = record
    before = previous.get("files", {})
    added = sorted(set(records) - set(before))
    removed = sorted(set(before) - set(records))
    modified = sorted(k for k in records.keys() & before.keys() if records[k]["sha256"] != before[k]["sha256"])
    renames = []
    for src in removed:
        for dest in added:
            if before[src]["sha256"] == records[dest]["sha256"]:
                renames.append({"from": src, "to": dest})
                break
    result = {"version": VERSION, "analyzer_version": ANALYZER_VERSION, "policy_hash": policy_hash,
              "files": records, "inputs_hash": digest({k: v.get("semantic_sha256", v["sha256"]) for k, v in records.items()})}
    if persist:
        write_json(path, result)
    return result, {"added": added, "modified": modified, "removed": removed, "renamed": renames,
                    "files_read": reads, "ast_parses": parses}


def contracts_index(root, persist=False, full=False):
    inv, stats = inventory(root, persist=persist, full=full)
    modules = {k: v["contracts"] for k, v in inv["files"].items() if "contracts" in v}
    result = {"version": "6.0", "analyzer_version": ANALYZER_VERSION, "project": Path(root).name,
              "$schema": "../schemas/contracts_ast.schema.json",
              "topology_hash": read_json(Path(root) / ".context/tree.json").get("topology_hash", ""),
              "inputs_hash": inv["inputs_hash"], "modules": modules,
              "public_symbols": sorted({s for m in modules.values() for s in m["symbols"]}),
              "cli_flags": sorted({s for m in modules.values() for s in m["cli_flags"]}),
              "signatures_1line": [s for m in modules.values() for s in m["signatures"]]}
    result["contracts_ast_hash"] = digest(modules)
    if persist:
        write_json(Path(root) / ".context/contracts_ast.json", result)
    return result, stats


def input_hash(inv, layer):
    files = inv["files"]
    if layer == "seed":
        files = {k: v for k, v in files.items() if not k.startswith("01_seed/") and k not in {"README.md", "README_ES.md"}}
    elif layer == "readme":
        files = {k: v for k, v in files.items() if k not in {"README.md", "README_ES.md"}}
    return digest({"analyzer": ANALYZER_VERSION, "policy": inv["policy_hash"], "files": {k: v.get("semantic_sha256", v["sha256"]) for k, v in files.items()}})


def estimated_tokens(value):
    text = value if isinstance(value, str) else json.dumps(value, ensure_ascii=False, separators=(",", ":"))
    return (len(text) + 2) // 3


def _context_budget(root, tier):
    path = Path(root) / "config/context_policy.json"
    policy = json.loads(path.read_text(encoding="utf-8")) if path.is_file() else {}
    if tier == "ecosystem":
        value = policy.get("budgets", {}).get("ecosystem_pack_max_tokens", 650)
    else:
        value = policy.get("profiles", {}).get("tier_" + tier, {}).get("target_token_budget", 220 if tier == "1a" else 800)
    if isinstance(value, bool) or not isinstance(value, int) or value <= 0:
        raise ValueError("Context token budget must be a positive integer")
    return value


def bounded(payload, limit, removable=("contracts_ast", "edges", "files", "active_topology", "layers")):
    result = json.loads(json.dumps(payload))
    omitted = 0
    for key in removable:
        while estimated_tokens(result) > limit and result.get(key):
            collection = result[key]
            if isinstance(collection, dict):
                collection.pop(next(reversed(collection)))
            elif isinstance(collection, list):
                collection.pop()
            else:
                result[key] = ""
            omitted += 1
            result["omitted"] = omitted
            result["expand"] = "--expand"
    if estimated_tokens(result) > limit:
        raise ValueError("Required context exceeds budget; use --expand")
    return result


def _orientation_stamp(root):
    result = []
    for name in (".agentignore", ".gitignore", "config/context_policy.json"):
        path = Path(root) / name
        if path.is_file():
            st = path.stat()
            result.append([name, st.st_size, st.st_mtime_ns])
    return result


def _orientation_beacons(root, target):
    parts = Path(target).parts
    if ".." in parts or Path(target).is_absolute():
        raise ValueError("Orientation target must remain relative to its project")
    directory = Path(root)
    content, blocked = [], False
    for component in (None, *parts):
        if component not in (None, "."):
            directory = directory / component
        path = directory / ".context.yaml"
        if path.is_file():
            raw = path.read_bytes()
            content.append(digest(raw))
            blocked = blocked or bool(re.search(r"(?mi)^\s*crawl\s*:\s*false\s*(?:#.*)?$", raw.decode("utf-8", errors="replace")))
    return digest(content), blocked


_ORIENTATION_READ_CACHE = {}


def query_orientation(root, target=".", tier="1a", expand=False):
    """Fast recorded view. Return None when a verified cache cannot be used."""
    root = Path(root)
    target = target.replace("\\", "/").removeprefix("./").rstrip("/") or "."
    (root / target).resolve().relative_to(root.resolve())
    cache_file = root / ".context/orientation_cache.json"
    if not cache_file.is_file():
        return None
    stamp = cache_file.stat().st_mtime_ns
    cached_stamp, table = _ORIENTATION_READ_CACHE.get(str(root), (None, {}))
    if cached_stamp != stamp:
        table = read_json(cache_file)
        _ORIENTATION_READ_CACHE[str(root)] = (stamp, table)
    entry = table.get("entries", {}).get(target)
    if not entry or table.get("policy_stamp") != _orientation_stamp(root):
        return None
    chain_hash, blocked = _orientation_beacons(root, target)
    if blocked:
        return {"idir_pack": "6.0", "focus": target, "crawl": False, "state": "pruned", "files": [], "edges": {}}
    if entry.get("beacon_chain_hash") != chain_hash:
        return None
    value = json.loads(json.dumps(entry["pack"]))
    value.update(tier=tier, state="recorded", generation=table.get("generation"))
    from stat import S_ISREG
    verified = []
    for item in value.get("files", []):
        name = item.rsplit("(~", 1)[0]
        path = root / target / name
        try:
            st = path.stat()
            if S_ISREG(st.st_mode):
                ratio = 3.6 if path.suffix.lower() in {".py", ".sql", ".json", ".yaml", ".yml", ".avsc", ".tf", ".sh", ".ps1", ".toml"} else 4
                binary = path.suffix.lower() in {".png", ".jpg", ".jpeg", ".gif", ".ico", ".webp", ".bmp", ".pbix", ".parquet", ".delta", ".avro", ".orc", ".feather", ".pdf", ".zip", ".tar", ".gz", ".7z", ".whl", ".pyc", ".pyd", ".so", ".dll", ".exe"}
                verified.append(f"{name}(~{0 if binary else max(1, int(st.st_size / ratio))}t)")
        except OSError:
            pass
    value["files"] = verified
    checkpoint = read_json(root / ".context/checkpoint.json")
    if (checkpoint.get("status") in {"executing", "approved", "paused"}
            and (not checkpoint.get("expires_at") or checkpoint["expires_at"] > datetime.now(timezone.utc).isoformat())):
        value["checkpoint"] = {"plan_id": checkpoint.get("plan_id"), "session_id": checkpoint.get("session_id"),
            "objective": checkpoint.get("objective", "")[:80], "constraints": [str(v)[:80] for v in checkpoint.get("constraints", [])[:2]],
            "phase": checkpoint.get("current_phase"), "next": checkpoint.get("next_action", "")[:80]}
    return value if expand else bounded(value, _context_budget(root, tier))


def validate_seed(path, index=None):
    text = Path(path).read_text(encoding="utf-8")
    errors = []
    if not re.search(r'<SEED_ARCHITECTURAL_VECTOR\b[^>]*contains_source_code="false"', text) or "</SEED_ARCHITECTURAL_VECTOR>" not in text:
        errors.append("Missing architectural vector container")
    if "CONTEXT HANDOFF" not in text or "0.1" not in text:
        errors.append("Missing receiver instructions or handoff")
    if not {str(n) for n in range(11)}.issubset(set(re.findall(r"(?m)^##\s+(\d+)\.", text))):
        errors.append("Missing numbered architectural sections 0 through 10")
    if index is not None:
        expected = {symbol for name, module in index.get("modules", {}).items()
                    if not (name.startswith("tests/") or "/tests/" in name) for symbol in module.get("symbols", [])}
        missing = sorted(symbol for symbol in expected if symbol not in text)
        if missing:
            errors.append("Missing public contracts: " + ", ".join(missing[:20]))
    if re.search(r"(?<![A-Za-z0-9_])[A-Za-z]:[/\\]|file:///|(?<![:/A-Za-z0-9])/(?:home|Users)/", text):
        errors.append("Local absolute path")
    for language, body in re.findall(r"```([^\n]*)\n(.*?)```", text, re.S):
        if language.strip() in {"yaml", "yml"} and body.lstrip().startswith("seed_schema_version:"):
            # Seed identity metadata is a contract, not implementation source.
            continue
        if language.strip() in {"python", "py", "sh", "bash", "ps1", "sql", "json", "yaml", "rust", "go"} and len(body.strip().splitlines()) > 5:
            errors.append("Implementation block exceeds five lines")
    return errors


def validate_readmes(root):
    errors = []
    headings = []
    for name, other in (("README.md", "README_ES.md"), ("README_ES.md", "README.md")):
        path = Path(root) / name
        if not path.is_file():
            errors.append(f"Missing {name}")
            continue
        text = path.read_text(encoding="utf-8")
        sections = re.findall(r"(?m)^##\s+(\d+)\.", text)
        headings.append(sections)
        if sections != [str(i) for i in range(1, 9)]:
            errors.append(f"{name}: expected eight ordered sections")
        # Absolute paths are valid in fenced terminal examples when users request
        # copy-pasteable commands. Keep authored prose free of machine-local paths.
        prose = re.sub(r"```.*?```", "", text, flags=re.S)
        if other not in text or re.search(r"(?<![A-Za-z0-9_])[A-Za-z]:[/\\]|file:///|(?<![:/A-Za-z0-9])/(?:home|Users)/", prose):
            errors.append(f"{name}: invalid language links or local paths")
    if len(headings) == 2 and headings[0] != headings[1]:
        errors.append("Language section mismatch")
    return errors

"""Versioned iContext bundles for Antigravity and Codex. Never replace user rules."""
import json
import os
import shutil
import sys
import time
from pathlib import Path

from context_runtime import VERSION, atomic_write, digest, read_json, write_json

SKILLS = {"idir": ("iDirectory", "skills/v6/idir"),
          "seed": ("ThinkingSeed", "skills/v6/seed"),
          "seed-master": ("ThinkingSeed", "skills/v6/seed-master"),
          "metrics": ("MetricsThinking", "skills/v6/metrics"),
          "readme": ("iReadme", "skills/v6/readme"),
          "icontext": ("ContextControl", "skills/v6/icontext")}

BOOTSTRAP = '''#!/usr/bin/env python3
