    }

    #[test]
    fn test_high_entropy() {
        let ent = fast_shannon_entropy("placeholder_key_abcdefghijklmnopqrstuvwxyz0123456789+/=");
        assert!(ent > 4.5);
    }
}

use pyo3::prelude::*;
use std::collections::HashMap;

mod ast_graph;
mod ballast_tokens;
mod entropy_sec;
mod walker;

use ast_graph::analyze_python_dependencies;
use ballast_tokens::calculate_shingling_jaccard as calc_jaccard;
use entropy_sec::fast_shannon_entropy as calc_entropy;
use walker::walk_directory;

#[pyfunction]
#[pyo3(signature = (path, ignore_patterns=None, include_content=true))]
fn scan_directory(
    py: Python<'_>,
    path: &str,
    ignore_patterns: Option<Vec<String>>,
    include_content: Option<bool>,
) -> PyResult<PyObject> {
    let pats = ignore_patterns.unwrap_or_default();
    let inc = include_content.unwrap_or(true);

    match walk_directory(path, &pats, inc) {
        Ok(records) => {
            let json_str = serde_json::to_string(&records)
                .map_err(|e| pyo3::exceptions::PyValueError::new_err(e.to_string()))?;
            let json_module = py.import("json")?;
            let py_val = json_module.call_method1("loads", (json_str,))?;
            Ok(py_val.into())
        }
        Err(e) => Err(pyo3::exceptions::PyIOError::new_err(e)),
    }
}

#[pyfunction]
fn fast_shannon_entropy(data: &str) -> PyResult<f64> {
    Ok(calc_entropy(data))
}

#[pyfunction]
#[pyo3(signature = (a, b, k=3))]
fn calculate_shingling_jaccard(a: &str, b: &str, k: Option<usize>) -> PyResult<f64> {
    Ok(calc_jaccard(a, b, k.unwrap_or(3)))
}

#[pyfunction]
fn compute_ast_coupling(
    py: Python<'_>,
    python_files: HashMap<String, String>,
) -> PyResult<PyObject> {
    let metrics = analyze_python_dependencies(&python_files);
    let json_str = serde_json::to_string(&metrics)
        .map_err(|e| pyo3::exceptions::PyValueError::new_err(e.to_string()))?;
    let json_module = py.import("json")?;
    let py_val = json_module.call_method1("loads", (json_str,))?;
    Ok(py_val.into())
}

#[pymodule]
fn _core_rs(_py: Python<'_>, m: &PyModule) -> PyResult<()> {
    m.add_function(wrap_pyfunction!(scan_directory, m)?)?;
    m.add_function(wrap_pyfunction!(fast_shannon_entropy, m)?)?;
    m.add_function(wrap_pyfunction!(calculate_shingling_jaccard, m)?)?;
    m.add_function(wrap_pyfunction!(compute_ast_coupling, m)?)?;
    Ok(())
}

use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use std::fs;
use std::path::Path;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ScannedFileRecord {
    pub path: String,
    pub size_bytes: usize,
    pub line_count: usize,
    pub sha256: String,
    pub token_estimate: usize,
    pub content: Option<String>,
}

pub fn walk_directory(
    root_path: &str,
    ignore_patterns: &[String],
    include_content: bool,
) -> Result<Vec<ScannedFileRecord>, String> {
    let root = Path::new(root_path);
    if !root.exists() {
        return Err(format!("Root directory does not exist: {}", root_path));
    }

    let mut records = Vec::new();
    let mut stack = vec![root.to_path_buf()];

    while let Some(current_dir) = stack.pop() {
        let entries = match fs::read_dir(&current_dir) {
            Ok(e) => e,
            Err(_) => continue,
        };

        for entry in entries.flatten() {
            let path = entry.path();
            let rel_path = match path.strip_prefix(root) {
                Ok(p) => p.to_string_lossy().replace('\\', "/"),
                Err(_) => path.to_string_lossy().replace('\\', "/"),
            };

            // Check ignore patterns
            let mut skip = false;
            for pat in ignore_patterns {
                if rel_path.starts_with(pat) || rel_path.contains(&format!("/{}/", pat)) || rel_path.ends_with(pat) {
                    skip = true;
                    break;
                }
            }
            if skip || rel_path == ".git" || rel_path.starts_with(".git/") || rel_path.contains("__pycache__") {
                continue;
            }

            if path.is_dir() {
                stack.push(path);
            } else if path.is_file() {
                if let Ok(metadata) = entry.metadata() {
                    let size_bytes = metadata.len() as usize;

                    // Read content safely up to 2MB
                    let content_str = if size_bytes < 2 * 1024 * 1024 {
                        fs::read_to_string(&path).ok()
                    } else {
                        None
                    };

                    let line_count = content_str.as_ref().map(|s| s.lines().count()).unwrap_or(0);
                    let token_estimate = size_bytes / 4;

                    // Compute SHA-256
                    let mut hasher = Sha256::new();
                    if let Some(ref c) = content_str {
                        hasher.update(c.as_bytes());
                    } else if let Ok(bytes) = fs::read(&path) {
                        hasher.update(&bytes);
                    }
                    let hash_str = format!("{:x}", hasher.finalize());

                    records.push(ScannedFileRecord {
                        path: rel_path,
                        size_bytes,
                        line_count,
                        sha256: hash_str,
                        token_estimate,
                        content: if include_content { content_str } else { None },
                    });
                }
            }
        }
    }

    records.sort_by(|a, b| a.path.cmp(&b.path));
    Ok(records)
}

