        return AuditCriterion(
            criterion_id=cfg["id"],
            name=cfg["name"],
            fulfilled=fulfilled,
            evidence_path="src/metricsthinking/backends/python_fallback.py" if "src/metricsthinking/backends/python_fallback.py" in ev.rel_files else None,
