    with repository_lock(root):
        sidecar = root / ".context" / "layers" / f"{name}.json"
        previous = read_json(sidecar)
        value = {"version": VERSION, **payload}
        if {k: v for k, v in previous.items() if k != "published_at"} == value:
            value = previous
        else:
            value["published_at"] = datetime.now(timezone.utc).isoformat()
        write_json(sidecar, value)
        bus_path = root / ".context" / "icontext_bus.json"
        old_bus = read_json(bus_path)
        layers = dict(old_bus.get("layers", {}))
        for key in LAYER_NAMES.values():
            record = read_json(root / ".context" / "layers" / f"{key}.json")
            if record:
                layers[key] = record
            elif key not in layers:
                layers[key] = {"present": False, "state": "unknown"}
        for record in layers.values():
            record.setdefault("state", "legacy_unverified")
        bus = {"$schema": "../schemas/icontext_bus.schema.json", "protocol_version": VERSION, "project": root.name, "layers": layers}
        if {k: v for k, v in old_bus.items() if k != "updated_at"} == bus:
            return old_bus
        bus["updated_at"] = datetime.now(timezone.utc).isoformat()
        write_json(bus_path, bus)
        return bus


def ignore_patterns(root):
    patterns = []
    for name in (".gitignore", ".agentignore"):
        path = Path(root) / name
        if path.is_file():
            patterns.extend(line.strip() for line in path.read_text(encoding="utf-8").splitlines()
                            if line.strip() and not line.lstrip().startswith("#"))
    return patterns


def ignored(relative, patterns):
    result = False
    for pattern in patterns:
        negate = pattern.startswith("!")
        pattern = pattern.lstrip("!").strip("/")
        parts = relative.split("/")
        if (fnmatch.fnmatchcase(relative, pattern) or relative.startswith(pattern + "/")
                or ("/" not in pattern and any(fnmatch.fnmatchcase(p, pattern) for p in parts))):
            result = not negate
    return result


def crawl_allowed(directory):
    beacon = Path(directory) / ".context.yaml"
    if beacon.is_file():
        return not re.search(r"(?mi)^\s*crawl\s*:\s*false\s*(?:#.*)?$", beacon.read_text(encoding="utf-8"))
    return True


def iter_files(root, patterns=None):
    """Prune before descending, including inherited beacon restrictions."""
    root = Path(root).resolve()
    patterns = ignore_patterns(root) + (patterns or [])
    if not crawl_allowed(root):
        return
    for current, dirs, files in os.walk(root, followlinks=False):
        cur = Path(current)
        dirs[:] = sorted(d for d in dirs if d not in EXCLUDED
                         and not (cur / d).is_symlink()
                         and (cur / d).relative_to(root).as_posix() not in PRUNED
                         and not ignored((cur / d).relative_to(root).as_posix(), patterns)
                         and crawl_allowed(cur / d))
        for name in sorted(files):
            path = cur / name
            rel = path.relative_to(root).as_posix()
            if (path.is_symlink() or name.startswith(".tmp_") or name == ".DS_Store"
                    or name == "desktop.ini" or name.endswith((".pyc", ".coverage")) or ignored(rel, patterns)):
                continue
            if name.startswith(".") and name not in {".context.yaml", ".gitignore", ".agentignore", ".cursorrules"}:
                continue
            yield path


def python_contracts(source, relative):
    import ast
    tree = ast.parse(source)
    symbols, signatures, flags, imports = [], [], [], []
    for node in tree.body:
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and not node.name.startswith("_"):
            symbols.append(node.name)
            signatures.append(f"./{relative}::{node.name}({ast.unparse(node.args)}) -> {ast.unparse(node.returns) if node.returns else 'Any'}")
        elif isinstance(node, ast.ClassDef) and not node.name.startswith("_"):
            symbols.append(node.name)
            signatures.append(f"./{relative}::{node.name}(class)")
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            imports.extend(a.name for a in node.names)
        elif isinstance(node, ast.ImportFrom):
            imports.append(node.module or "")
        elif isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and node.func.attr == "add_argument":
            flags.extend(a.value for a in node.args if isinstance(a, ast.Constant) and isinstance(a.value, str) and a.value.startswith("-"))
    return {"symbols": symbols, "signatures": signatures, "cli_flags": sorted(set(flags)), "imports": sorted(set(imports))}


def inventory(root, persist=False, full=False):
    root = Path(root).resolve()
    path = root / ".context" / "inventory.json"
    previous = read_json(path)
    patterns = ignore_patterns(root)
    policy_hash = digest([patterns, ANALYZER_VERSION, read_json(root / "config/context_policy.json")])
    old = previous.get("files", {}) if previous.get("policy_hash") == policy_hash else {}
    records, reads, parses = {}, 0, 0
    for file in iter_files(root, patterns):
        rel = file.relative_to(root).as_posix()
        stat = file.stat()
        cached = old.get(rel, {})
        stamp = [stat.st_size, stat.st_mtime_ns]
        if not full and cached.get("stat") == stamp:
            records[rel] = cached
            continue
        raw = file.read_bytes()
        reads += 1
        record = {"stat": stamp, "sha256": digest(raw), "size": len(raw)}
        if rel in {"README.md", "README_ES.md"}:
            text = raw.decode("utf-8", errors="replace")
            text = re.sub(r"<!-- ICONTEXT-V6:TELEMETRY:START -->.*?<!-- ICONTEXT-V6:TELEMETRY:END -->", "", text, flags=re.S)
            text = re.sub(r"\n{3,}", "\n\n", text.strip())
            record["semantic_sha256"] = digest(text.encode("utf-8"))
        if file.suffix == ".py":
            if cached.get("sha256") == record["sha256"] and "contracts" in cached:
                record["contracts"] = cached["contracts"]
            else:
                parses += 1
                try:
                    record["contracts"] = python_contracts(raw.decode("utf-8-sig"), rel)
                except (SyntaxError, UnicodeError) as exc:
                    record["parse_error"] = str(exc)
        records[rel] = record
    before = previous.get("files", {})
    added = sorted(set(records) - set(before))
    removed = sorted(set(before) - set(records))
    modified = sorted(k for k in records.keys() & before.keys() if records[k]["sha256"] != before[k]["sha256"])
    renames = []
    for src in removed:
        for dest in added:
            if before[src]["sha256"] == records[dest]["sha256"]:
                renames.append({"from": src, "to": dest})
                break
    result = {"version": VERSION, "analyzer_version": ANALYZER_VERSION, "policy_hash": policy_hash,
              "files": records, "inputs_hash": digest({k: v.get("semantic_sha256", v["sha256"]) for k, v in records.items()})}
    if persist:
        write_json(path, result)
    return result, {"added": added, "modified": modified, "removed": removed, "renamed": renames,
                    "files_read": reads, "ast_parses": parses}


def contracts_index(root, persist=False, full=False):
    inv, stats = inventory(root, persist=persist, full=full)
    modules = {k: v["contracts"] for k, v in inv["files"].items() if "contracts" in v}
    result = {"version": "6.0", "analyzer_version": ANALYZER_VERSION, "project": Path(root).name,
              "$schema": "../schemas/contracts_ast.schema.json",
              "topology_hash": read_json(Path(root) / ".context/tree.json").get("topology_hash", ""),
              "inputs_hash": inv["inputs_hash"], "modules": modules,
              "public_symbols": sorted({s for m in modules.values() for s in m["symbols"]}),
              "cli_flags": sorted({s for m in modules.values() for s in m["cli_flags"]}),
              "signatures_1line": [s for m in modules.values() for s in m["signatures"]]}
    result["contracts_ast_hash"] = digest(modules)
    if persist:
        write_json(Path(root) / ".context/contracts_ast.json", result)
    return result, stats


def input_hash(inv, layer):
    files = inv["files"]
    if layer == "seed":
        files = {k: v for k, v in files.items() if not k.startswith("01_seed/") and k not in {"README.md", "README_ES.md"}}
    elif layer == "readme":
        files = {k: v for k, v in files.items() if k not in {"README.md", "README_ES.md"}}
    return digest({"analyzer": ANALYZER_VERSION, "policy": inv["policy_hash"], "files": {k: v.get("semantic_sha256", v["sha256"]) for k, v in files.items()}})


def estimated_tokens(value):
    text = value if isinstance(value, str) else json.dumps(value, ensure_ascii=False, separators=(",", ":"))
    return (len(text) + 2) // 3


def _context_budget(root, tier):
    path = Path(root) / "config/context_policy.json"
    policy = json.loads(path.read_text(encoding="utf-8")) if path.is_file() else {}
    if tier == "ecosystem":
        value = policy.get("budgets", {}).get("ecosystem_pack_max_tokens", 650)
    else:
        value = policy.get("profiles", {}).get("tier_" + tier, {}).get("target_token_budget", 220 if tier == "1a" else 800)
    if isinstance(value, bool) or not isinstance(value, int) or value <= 0:
        raise ValueError("Context token budget must be a positive integer")
    return value


def bounded(payload, limit, removable=("contracts_ast", "edges", "files", "active_topology", "layers")):
    result = json.loads(json.dumps(payload))
    omitted = 0
    for key in removable:
        while estimated_tokens(result) > limit and result.get(key):
            collection = result[key]
            if isinstance(collection, dict):
                collection.pop(next(reversed(collection)))
            elif isinstance(collection, list):
                collection.pop()
            else:
                result[key] = ""
            omitted += 1
            result["omitted"] = omitted
            result["expand"] = "--expand"
    if estimated_tokens(result) > limit:
        raise ValueError("Required context exceeds budget; use --expand")
    return result


def _orientation_stamp(root):
    result = []
    for name in (".agentignore", ".gitignore", "config/context_policy.json"):
        path = Path(root) / name
        if path.is_file():
            st = path.stat()
            result.append([name, st.st_size, st.st_mtime_ns])
    return result


def _orientation_beacons(root, target):
    parts = Path(target).parts
    if ".." in parts or Path(target).is_absolute():
        raise ValueError("Orientation target must remain relative to its project")
    directory = Path(root)
    content, blocked = [], False
    for component in (None, *parts):
        if component not in (None, "."):
            directory = directory / component
        path = directory / ".context.yaml"
        if path.is_file():
            raw = path.read_bytes()
            content.append(digest(raw))
            blocked = blocked or bool(re.search(r"(?mi)^\s*crawl\s*:\s*false\s*(?:#.*)?$", raw.decode("utf-8", errors="replace")))
    return digest(content), blocked


_ORIENTATION_READ_CACHE = {}


def query_orientation(root, target=".", tier="1a", expand=False):
    """Fast recorded view. Return None when a verified cache cannot be used."""
    root = Path(root)
    target = target.replace("\\", "/").removeprefix("./").rstrip("/") or "."
    (root / target).resolve().relative_to(root.resolve())
    cache_file = root / ".context/orientation_cache.json"
    if not cache_file.is_file():
        return None
    stamp = cache_file.stat().st_mtime_ns
    cached_stamp, table = _ORIENTATION_READ_CACHE.get(str(root), (None, {}))
    if cached_stamp != stamp:
        table = read_json(cache_file)
        _ORIENTATION_READ_CACHE[str(root)] = (stamp, table)
    entry = table.get("entries", {}).get(target)
    if not entry or table.get("policy_stamp") != _orientation_stamp(root):
        return None
    chain_hash, blocked = _orientation_beacons(root, target)
    if blocked:
        return {"idir_pack": "6.0", "focus": target, "crawl": False, "state": "pruned", "files": [], "edges": {}}
    if entry.get("beacon_chain_hash") != chain_hash:
        return None
    value = json.loads(json.dumps(entry["pack"]))
    value.update(tier=tier, state="recorded", generation=table.get("generation"))
    from stat import S_ISREG
    verified = []
    for item in value.get("files", []):
        name = item.rsplit("(~", 1)[0]
        path = root / target / name
        try:
            st = path.stat()
            if S_ISREG(st.st_mode):
                ratio = 3.6 if path.suffix.lower() in {".py", ".sql", ".json", ".yaml", ".yml", ".avsc", ".tf", ".sh", ".ps1", ".toml"} else 4
                binary = path.suffix.lower() in {".png", ".jpg", ".jpeg", ".gif", ".ico", ".webp", ".bmp", ".pbix", ".parquet", ".delta", ".avro", ".orc", ".feather", ".pdf", ".zip", ".tar", ".gz", ".7z", ".whl", ".pyc", ".pyd", ".so", ".dll", ".exe"}
                verified.append(f"{name}(~{0 if binary else max(1, int(st.st_size / ratio))}t)")
        except OSError:
            pass
    value["files"] = verified
    checkpoint = read_json(root / ".context/checkpoint.json")
    if (checkpoint.get("status") in {"executing", "approved", "paused"}
            and (not checkpoint.get("expires_at") or checkpoint["expires_at"] > datetime.now(timezone.utc).isoformat())):
        value["checkpoint"] = {"plan_id": checkpoint.get("plan_id"), "session_id": checkpoint.get("session_id"),
            "objective": checkpoint.get("objective", "")[:80], "constraints": [str(v)[:80] for v in checkpoint.get("constraints", [])[:2]],
            "phase": checkpoint.get("current_phase"), "next": checkpoint.get("next_action", "")[:80]}
    return value if expand else bounded(value, _context_budget(root, tier))


def validate_seed(path, index=None):
    text = Path(path).read_text(encoding="utf-8")
    errors = []
    if not re.search(r'<SEED_ARCHITECTURAL_VECTOR\b[^>]*contains_source_code="false"', text) or "</SEED_ARCHITECTURAL_VECTOR>" not in text:
        errors.append("Missing architectural vector container")
    if "CONTEXT HANDOFF" not in text or "0.1" not in text:
        errors.append("Missing receiver instructions or handoff")
    if not {str(n) for n in range(11)}.issubset(set(re.findall(r"(?m)^##\s+(\d+)\.", text))):
        errors.append("Missing numbered architectural sections 0 through 10")
    if index is not None:
        expected = {symbol for name, module in index.get("modules", {}).items()
                    if not (name.startswith("tests/") or "/tests/" in name) for symbol in module.get("symbols", [])}
        missing = sorted(symbol for symbol in expected if symbol not in text)
        if missing:
            errors.append("Missing public contracts: " + ", ".join(missing[:20]))
    if re.search(r"(?<![A-Za-z0-9_])[A-Za-z]:[/\\]|file:///|(?<![:/A-Za-z0-9])/(?:home|Users)/", text):
        errors.append("Local absolute path")
    for language, body in re.findall(r"```([^\n]*)\n(.*?)```", text, re.S):
        if language.strip() in {"yaml", "yml"} and body.lstrip().startswith("seed_schema_version:"):
            # Seed identity metadata is a contract, not implementation source.
            continue
        if language.strip() in {"python", "py", "sh", "bash", "ps1", "sql", "json", "yaml", "rust", "go"} and len(body.strip().splitlines()) > 5:
            errors.append("Implementation block exceeds five lines")
    return errors


def validate_readmes(root):
    errors = []
    headings = []
    for name, other in (("README.md", "README_ES.md"), ("README_ES.md", "README.md")):
        path = Path(root) / name
        if not path.is_file():
            errors.append(f"Missing {name}")
            continue
        text = path.read_text(encoding="utf-8")
        sections = re.findall(r"(?m)^##\s+(\d+)\.", text)
        headings.append(sections)
        if sections != [str(i) for i in range(1, 9)]:
            errors.append(f"{name}: expected eight ordered sections")
        # Absolute paths are valid in fenced terminal examples when users request
        # copy-pasteable commands. Keep authored prose free of machine-local paths.
        prose = re.sub(r"```.*?```", "", text, flags=re.S)
        if other not in text or re.search(r"(?<![A-Za-z0-9_])[A-Za-z]:[/\\]|file:///|(?<![:/A-Za-z0-9])/(?:home|Users)/", prose):
            errors.append(f"{name}: invalid language links or local paths")
    if len(headings) == 2 and headings[0] != headings[1]:
        errors.append("Language section mismatch")
    return errors

#!/usr/bin/env python3
"""
test_seed_coverage.py - Benchmark y Auditoría Determinista para ThinkingSeed v3.0
Evalúa cuantitativamente el % de cobertura del ADN de un proyecto y audita los
6 invariantes deterministas del estándar ThinkingSeed v3.0 usando exclusivamente
la librería estándar de Python:
1. check_llm_contract_headers: Contrato XML <SEED_ARCHITECTURAL_VECTOR>, 0.1 y CONTEXT HANDOFF
2. check_zero_code_invariant: Prohibición de código fuente de implementación inyectado
3. check_path_portability: Cero rutas absolutas locales y cero URIs file:///
4. check_secret_leaks: Escaneo determinista Zero-Trust (<REDACTED>)
5. check_ast_contract_coverage: Cobertura semántica de contratos públicos y CLI flags vía AST
6. check_local_tree_freshness: Sincronización nativa entre beacons .context.yaml, tree.json y all-lowercase
"""

import os
import sys
import re
import ast
import json
import argparse
from pathlib import Path
from typing import Dict, List, Set, Tuple, Any

IGNORE_DIRS: Set[str] = {
    '.git', '.venv', 'venv', '__pycache__', '.pytest_cache',
    'node_modules', '.mypy_cache', '.ruff_cache', 'dist', 'build'
}

FORBIDDEN_CODE_LANGS: Set[str] = {
    'python', 'py', 'powershell', 'ps1', 'bash', 'sh', 'shell', 'zsh',
    'json', 'rust', 'rs', 'go', 'golang', 'sql', 'javascript', 'js',
    'typescript', 'ts', 'c', 'cpp', 'csharp', 'java', 'ruby', 'php'
}

ALLOWED_STRUCTURAL_LANGS: Set[str] = {
    '', 'text', 'plaintext', 'ascii', 'yaml', 'yml', 'mermaid', 'markdown', 'md'
}


def check_llm_contract_headers(seed_content: str) -> Dict[str, Any]:
    """Validador 1: Verifica la presencia del contenedor XML v3.0, sección 0.1 y CONTEXT HANDOFF."""
    has_xml_open = '<SEED_ARCHITECTURAL_VECTOR' in seed_content and 'contains_source_code="false"' in seed_content
    has_xml_close = '</SEED_ARCHITECTURAL_VECTOR>' in seed_content
    has_section_0_1 = '0.1 Instrucciones para el modelo receptor' in seed_content
    has_context_handoff = 'CONTEXT HANDOFF' in seed_content

    missing = []
    if not has_xml_open:
        missing.append('<SEED_ARCHITECTURAL_VECTOR ... contains_source_code="false">')
    if not has_xml_close:
        missing.append('</SEED_ARCHITECTURAL_VECTOR>')
    if not has_section_0_1:
        missing.append('0.1 Instrucciones para el modelo receptor')
    if not has_context_handoff:
        missing.append('CONTEXT HANDOFF')

    return {
        'passed': len(missing) == 0,
        'has_xml_open': has_xml_open,
        'has_xml_close': has_xml_close,
        'has_section_0_1': has_section_0_1,
        'has_context_handoff': has_context_handoff,
        'missing': missing
    }


def check_zero_code_invariant(seed_content: str) -> Dict[str, Any]:
    """Validador 2: Escanea bloques cercados con triple backtick y bloquea código de implementación."""
    fence_pattern = re.compile(r'```([a-zA-Z0-9_-]*)\n(.*?)```', re.DOTALL)
    matches = fence_pattern.findall(seed_content)

    violations: List[str] = []
    yaml_blocks_seen = 0

    for idx, (lang, body) in enumerate(matches, start=1):
        lang_clean = lang.strip().lower()
        body_lines = [line for line in body.strip().splitlines() if line.strip()]
        num_lines = len(body_lines)

        if lang_clean in FORBIDDEN_CODE_LANGS:
            violations.append(f"Bloque #{idx} con lenguaje de implementación prohibido '{lang_clean}' ({num_lines} líneas)")
            continue

        if lang_clean not in ALLOWED_STRUCTURAL_LANGS:
            violations.append(f"Bloque #{idx} con etiqueta no autorizada '{lang_clean}' ({num_lines} líneas)")
            continue

        if lang_clean in ('yaml', 'yml'):
            yaml_blocks_seen += 1
            # Solo se permite el bloque YAML de metadatos en Sección 0 (o bloques <= 5 líneas)
            if yaml_blocks_seen > 1 and num_lines > 5:
                violations.append(f"Bloque YAML #{idx} adicional mayor a 5 líneas ({num_lines} líneas)")

    return {
        'passed': len(violations) == 0,
        'total_blocks': len(matches),
        'allowed_blocks': len(matches) - len(violations),
        'violations': violations
    }


def check_path_portability(seed_content: str) -> Dict[str, Any]:
    """Validador 3: Verifica 0 rutas absolutas locales y 0 URIs file:///."""
    portability_regex = re.compile(r'(file:///|[a-zA-Z]:[/\\]|/Users/[a-zA-Z0-9._-]+|/home/[a-zA-Z0-9._-]+)')
    found_matches = portability_regex.findall(seed_content)
    has_relative_root = bool(re.search(r'repository_root:\s*["\']\./["\']', seed_content))

    return {
        'passed': len(found_matches) == 0 and has_relative_root,
        'has_relative_root': has_relative_root,
        'matches': found_matches
    }


def check_secret_leaks(seed_content: str, seed_dir: Path = None) -> Dict[str, Any]:
    """Validador 4: Escaneo determinista Zero-Trust contra fugas de secretos en 01_seed/*.md."""
    secret_patterns = [
        ('Google API Key', re.compile(r'AIza[0-9A-Za-z\-_]{35}')),
        ('OpenAI/Anthropic Key', re.compile(r'\bsk-[A-Za-z0-9\-_]{20,}\b')),
        ('GitHub Token', re.compile(r'\bgh[pousr]_[A-Za-z0-9_]{20,}\b')),
        ('AWS Access Key', re.compile(r'\bAKIA[0-9A-Z]{16}\b')),
        ('PEM Private Key', re.compile(r'-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----')),
        ('Bearer Token Real', re.compile(r'Bearer\s+(?!<REDACTED>)[A-Za-z0-9\-\._~\+\/]{20,}')),
        ('Credential URI', re.compile(r'[a-zA-Z0-9+.-]+://[^/\s:@<]+:(?!<REDACTED>)[^/\s@<]+@[^\s"\'`]+'))
    ]

    leaks: List[str] = []
    targets: List[Tuple[str, str]] = [('current_seed', seed_content)]

    if seed_dir and seed_dir.exists():
        for md_file in sorted(seed_dir.glob('*.md')):
            try:
                targets.append((md_file.name, md_file.read_text(encoding='utf-8', errors='ignore')))
            except Exception:
                pass

    seen_leaks: Set[str] = set()
    for label, text in targets:
        for pat_name, pat_regex in secret_patterns:
            for m in pat_regex.findall(text):
                finding = f"{label}: {pat_name}"
                if finding not in seen_leaks:
                    seen_leaks.add(finding)
                    leaks.append(finding)

    has_redacted_tag = '<REDACTED>' in seed_content
    return {
        'passed': len(leaks) == 0 and has_redacted_tag,
        'leaks': leaks,
        'has_redacted_tag': has_redacted_tag
    }


def extract_repo_ast_contracts(repo_path: Path) -> Dict[str, List[str]]:
    """Validate content-backed v6 contracts, including working-tree changes."""
    sys.path.insert(0, str(Path(__file__).resolve().parent))
    from context_runtime import contracts_index
    index, _ = contracts_index(repo_path, persist=False)
    modules = {k: v for k, v in index["modules"].items() if not k.startswith("tests/")
               and not (k == "FWengine.py" and repo_path.name.lower() != "idirectory")}
    symbols = sorted({s for m in modules.values() for s in m["symbols"]})
    flags = sorted({s for m in modules.values() for s in m["cli_flags"]})
    return {"public_symbols": symbols, "cli_flags": flags, "all_contracts": symbols + flags}


def check_ast_contract_coverage(repo_path: Path, seed_content: str) -> Dict[str, Any]:
    """Validador 5: Mide el porcentaje de contratos simbólicos AST y CLI flags documentados en el Seed."""
    contracts = extract_repo_ast_contracts(repo_path)
    all_items = contracts['all_contracts']

    if not all_items:
        return {
            'passed': True,
            'matched': 0,
            'total': 0,
            'pct': 100.0,
            'symbols_matched': [],
            'missing': []
        }

    matched: List[str] = []
    missing: List[str] = []
    for item in all_items:
        if item in seed_content:
            matched.append(item)
        else:
            missing.append(item)

    pct = (len(matched) / len(all_items)) * 100.0
    return {
        'passed': pct >= 90.0,
        'matched': len(matched),
        'total': len(all_items),
        'pct': round(pct, 2),
        'symbols_matched': matched,
        'missing': missing
    }


def check_local_tree_freshness(repo_path: Path) -> Dict[str, Any]:
    """Validador 6: Verifica de forma autónoma que las carpetas con .context.yaml coincidan con .context/tree.json y cumplan all-lowercase."""
    beacon_dirs: Set[str] = set()
    uppercase_dirs: List[str] = []

    tree_file = repo_path / '.context' / 'tree.json'
    tree_nodes: Set[str] = set()
    expected_disk_nodes: Set[str] = set()
    nodes_dict: Dict[str, Any] = {}
    pruned_prefixes: List[str] = []
    if tree_file.exists():
        try:
            data = json.loads(tree_file.read_text(encoding='utf-8', errors='ignore'))
            nodes = data.get('nodes', {})
            if isinstance(nodes, dict):
                nodes_dict = nodes
                tree_nodes = set(nodes.keys())
                for k, v in nodes.items():
                    if isinstance(v, dict):
                        if v.get('exists', True) is not False:
                            expected_disk_nodes.add(k)
                        if v.get('crawl') is False:
                            pruned_prefixes.append(k.strip('/'))
        except Exception:
            pass

    for root, dirs, files in os.walk(repo_path):
        rel_root = os.path.relpath(root, repo_path).replace('\\', '/')
        if rel_root == '.':
            rel_root = ''
        dirs[:] = [
            d for d in dirs
            if d not in IGNORE_DIRS
            and (d == '.context' or not d.startswith('.'))
            and not any(
                f"{rel_root}/{d}".strip('/').startswith(pr + '/')
                for pr in pruned_prefixes
            )
        ]
        if rel_root:
            if not rel_root.startswith('.agents/skills/') and not rel_root.startswith('.'):
                for part in rel_root.split('/'):
                    if any(c.isupper() for c in part) and rel_root not in uppercase_dirs:
                        uppercase_dirs.append(rel_root)
            if '.context.yaml' in files:
                beacon_dirs.add(rel_root)

    # .context es un nodo de metadatos especial en tree.json donde .context.yaml es opcional
    if '.context' in expected_disk_nodes and (repo_path / '.context').is_dir():
        beacon_dirs.add('.context')

    # En iDirectory v5.0, los directorios ancestros intermedios tienen .context.yaml para herencia (resolve_beacon)
    intermediate_ancestors = {
        b for b in beacon_dirs
        if any(tn.startswith(b + '/') for tn in tree_nodes)
    }
    dynamic_children = {
        b for b in beacon_dirs
        if b not in expected_disk_nodes and (
            any(
                b.startswith(tn + '/') and isinstance(nodes_dict.get(tn), dict) and nodes_dict[tn].get('has_dynamic_children')
                for tn in tree_nodes
            )
            or b.split('/')[0] in ('artifacts', 'src', 'docs', '03_research', 'data', '02_foundation')
        )
    }
    comparable_beacons = beacon_dirs - intermediate_ancestors - dynamic_children

    missing_in_tree = sorted(list(comparable_beacons - expected_disk_nodes))
    missing_on_disk = sorted(list(expected_disk_nodes - beacon_dirs))

    passed = (
        tree_file.exists()
        and len(missing_in_tree) == 0
        and len(missing_on_disk) == 0
        and len(uppercase_dirs) == 0
    )

    return {
        'passed': passed,
        'beacons_count': len(comparable_beacons),
        'tree_nodes_count': len(expected_disk_nodes),
        'missing_in_tree': missing_in_tree,
        'missing_on_disk': missing_on_disk,
        'uppercase_dirs': sorted(uppercase_dirs)
    }


def analyze_repo(repo_path: Path) -> Dict[str, Any]:
    total_files = 0
    total_bytes = 0
    total_lines = 0
    ext_distribution: Dict[str, Dict[str, int]] = {}
    top_dirs: Set[str] = set()
    second_level_dirs: Set[str] = set()
    python_modules: List[str] = []
    scripts: List[str] = []
    config_files: List[str] = []
    data_files: List[str] = []

    for root, dirs, files in os.walk(repo_path):
        dirs[:] = [d for d in dirs if d not in IGNORE_DIRS]
        rel_root = os.path.relpath(root, repo_path).replace('\\', '/')

        if rel_root != '.':
            parts = rel_root.split('/')
            top_dirs.add(parts[0])
            if len(parts) >= 2:
                second_level_dirs.add(f"{parts[0]}/{parts[1]}")

        for f in files:
            p = Path(root) / f
            rel_f = os.path.normpath(os.path.join(rel_root, f)).replace('\\', '/')
            if rel_f.startswith('./'):
                rel_f = rel_f[2:]

            try:
                sz = p.stat().st_size
            except Exception:
                sz = 0

            total_files += 1
            total_bytes += sz
            ext = p.suffix.lower() or '[no_ext]'

            if ext not in ext_distribution:
                ext_distribution[ext] = {'files': 0, 'bytes': 0}
            ext_distribution[ext]['files'] += 1
            ext_distribution[ext]['bytes'] += sz

            if ext == '.py':
                python_modules.append(rel_f)
            if rel_f.startswith(('scripts/', 'tools/')):
                scripts.append(rel_f)
            if f.startswith('.') or ext in ('.toml', '.yaml', '.yml', '.ini', '.cfg', '.env'):
                config_files.append(rel_f)
            if ext in ('.tmdl', '.pbip', '.pbir', '.pbism', '.csv', '.parquet', '.avro', '.sql'):
                data_files.append(rel_f)

            if ext in ('.py', '.md', '.txt', '.json', '.yaml', '.yml', '.toml', '.tmdl', '.sql'):
                try:
                    with open(p, 'r', encoding='utf-8', errors='ignore') as fp:
                        total_lines += sum(1 for _ in fp)
                except Exception:
                    pass

    dependencies: Set[str] = set()
    pyproject = repo_path / 'pyproject.toml'
    if pyproject.exists():
        try:
            content = pyproject.read_text(encoding='utf-8', errors='ignore')
            matches = re.findall(r'["\']([a-zA-Z0-9_\-]+)(?:[>=<~^].*)?["\']', content)
            skip_words = {'name', 'version', 'description', 'authors', 'readme', 'python'}
            for m in matches:
                if len(m) > 2 and m.lower() not in skip_words:
                    dependencies.add(m.lower())
        except Exception:
            pass

    req_file = repo_path / 'requirements.txt'
    if req_file.exists():
        try:
            for line in req_file.read_text(encoding='utf-8', errors='ignore').splitlines():
                line = line.strip().split('#')[0].split(';')[0]
                dep = re.split(r'[=><~]', line)[0].strip()
                if dep:
                    dependencies.add(dep.lower())
        except Exception:
            pass

    ast_contracts = extract_repo_ast_contracts(repo_path)

    return {
        'repo_name': repo_path.resolve().name,
        'total_files': total_files,
        'total_bytes': total_bytes,
        'total_lines': total_lines,
        'ext_distribution': ext_distribution,
        'top_dirs': sorted(list(top_dirs)),
        'second_level_dirs': sorted(list(second_level_dirs)),
        'python_modules': sorted(python_modules),
        'scripts': sorted(scripts),
        'config_files': sorted(config_files),
        'data_files': sorted(data_files),
        'dependencies': sorted(list(dependencies)),
        'ast_contracts': ast_contracts['all_contracts']
    }


def analyze_seed(seed_path: Path) -> Dict[str, Any]:
    if not seed_path or not seed_path.exists():
        return {'exists': False}

    content = seed_path.read_text(encoding='utf-8', errors='ignore')
    lines = content.splitlines()
    words = len(content.split())
    chars = len(content)
    est_tokens = int(words * 1.3)

    conf = len(re.findall(r'\[CONFIRMADO\]', content))
    infer = len(re.findall(r'\[INFERIDO\]', content))
    falt = len(re.findall(r'\[FALTANTE\]', content))
    decl = len(re.findall(r'\[DECLARADO\]', content))

    headings = [l.strip() for l in lines if l.startswith('#')]
    has_handoff = 'CONTEXT HANDOFF' in content or 'PROTOCOLO DE ASISTENCIA' in content
    has_evidence_rules = 'REGLAS DE GENERACI' in content or 'Etiquetas de Evidencia' in content or 'Rigor Epistemológico' in content
    has_security_redact = '<REDACTED>' in content

    return {
        'exists': True,
        'size_bytes': len(content.encode('utf-8')),
        'lines': len(lines),
        'words': words,
        'chars': chars,
        'est_tokens': est_tokens,
        'epistemic': {
            'CONFIRMADO': conf,
            'INFERIDO': infer,
            'FALTANTE': falt,
            'DECLARADO': decl,
            'TOTAL_TAGS': conf + infer + falt + decl
        },
        'headings_count': len(headings),
        'has_handoff': has_handoff,
        'has_evidence_rules': has_evidence_rules,
        'has_security_redact': has_security_redact,
        'content_lower': content.lower(),
        'raw_content': content
    }


def compute_coverage(repo_meta: Dict[str, Any], seed_meta: Dict[str, Any], repo_path: Path) -> Dict[str, Any]:
    if not seed_meta.get('exists'):
        return {'covered': False}

    content = seed_meta['raw_content']
    content_lower = seed_meta['content_lower']

    def match_items(items: List[str], case_sensitive: bool = False) -> Tuple[int, int, float, List[str]]:
        if not items:
            return 0, 0, 100.0, []
        matched = []
        for it in items:
            needle = it if case_sensitive else it.lower()
            haystack = content if case_sensitive else content_lower
            base = os.path.basename(it)
            base_needle = base if case_sensitive else base.lower()
            if needle in haystack or base_needle in haystack:
                matched.append(it)
        score = (len(matched) / len(items)) * 100.0
        return len(matched), len(items), score, matched

    top_dir_m, top_dir_t, top_dir_pct, _ = match_items(repo_meta['top_dirs'])
    sec_dir_m, sec_dir_t, sec_dir_pct, _ = match_items(repo_meta['second_level_dirs'])
    scr_m, scr_t, scr_pct, _ = match_items(repo_meta['scripts'])
    py_m, py_t, py_pct, _ = match_items(repo_meta['python_modules'])
    dep_m, dep_t, dep_pct, _ = match_items(repo_meta['dependencies'])
    cfg_m, cfg_t, cfg_pct, _ = match_items(repo_meta['config_files'])

    # Ejecutar los 6 Validadores Deterministas v3.0
    v1_headers = check_llm_contract_headers(content)
    v2_zero_code = check_zero_code_invariant(content)
    v3_portability = check_path_portability(content)
    v4_secrets = check_secret_leaks(content, repo_path / '01_seed')
    v5_ast = check_ast_contract_coverage(repo_path, content)
    v6_freshness = check_local_tree_freshness(repo_path)

    # Ponderación de ADN Arquitectónico v3.0 (incluyendo cobertura semántica AST)
    adn_score = (
        (top_dir_pct * 0.20) +
        (sec_dir_pct * 0.15) +
        (dep_pct * 0.15) +
        (scr_pct * 0.15) +
        (min(py_pct * 2.5, 100.0) * 0.10) +
        (cfg_pct * 0.10) +
        (v5_ast['pct'] * 0.15)
    )

    # Penalización si fallan los contratos de identidad o portabilidad
    if not v1_headers['passed']:
        adn_score = max(0.0, adn_score - 15.0)
    if not v2_zero_code['passed']:
        adn_score = max(0.0, adn_score - 15.0)
    if not v3_portability['passed']:
        adn_score = max(0.0, adn_score - 15.0)

    all_gates_passed = (
        v1_headers['passed']
        and v2_zero_code['passed']
        and v3_portability['passed']
        and v4_secrets['passed']
        and v5_ast['passed']
        and v6_freshness['passed']
    )

    return {
        'covered': True,
        'top_dirs': {'matched': top_dir_m, 'total': top_dir_t, 'pct': top_dir_pct},
        'second_level_dirs': {'matched': sec_dir_m, 'total': sec_dir_t, 'pct': sec_dir_pct},
        'scripts': {'matched': scr_m, 'total': scr_t, 'pct': scr_pct},
        'python_modules': {'matched': py_m, 'total': py_t, 'pct': py_pct},
        'dependencies': {'matched': dep_m, 'total': dep_t, 'pct': dep_pct},
        'config_files': {'matched': cfg_m, 'total': cfg_t, 'pct': cfg_pct},
        'ast_contracts': {'matched': v5_ast['matched'], 'total': v5_ast['total'], 'pct': v5_ast['pct']},
        'validators': {
            'v1_headers': v1_headers,
            'v2_zero_code': v2_zero_code,
            'v3_portability': v3_portability,
            'v4_secrets': v4_secrets,
            'v5_ast': v5_ast,
            'v6_freshness': v6_freshness,
            'all_passed': all_gates_passed
        },
        'adn_score': round(adn_score, 2)
    }


